var HK_CH={"C01": "數與數線", "C02": "因數與倍數", "C03": "一元一次方程式與不等式", "C04": "二元一次聯立方程式與坐標", "C05": "比與比例", "C06": "乘法公式與多項式", "C07": "平方根與畢氏定理", "C08": "一元二次方程式", "C09": "數列與級數", "C10": "函數與二次函數", "C11": "三角形與多邊形", "C12": "平行與四邊形", "C13": "相似形", "C14": "圓", "C15": "三角形的心與幾何證明", "C16": "統計、機率與立體圖形"};
var HK=[{"id": "111-1", "y": 111, "no": 1, "ch": "C01", "img": "img/hk/111_1.webp", "gimg": null, "a": 0, "rate": 0.87, "t": "數線上誰的絕對值最小", "c": "絕對值就是「到原點的距離」，離原點 $O$ 最近的點，絕對值最小。", "st": [["把絕對值翻成距離", "題目問「哪個絕對值最小」，與其去猜 $a$、$b$、$c$、$d$ 的數字，不如記住：<br><br>$|a|$ 就是 $A$ 點到原點 $O$ 的距離，其他同理。"], ["看誰離原點最近", "從圖上看，$A$ 緊貼在 $O$ 的右邊，$D$、$C$ 在左邊比較遠，$B$ 在右邊更遠。<br><br>所以 $A$ 到 $O$ 的距離最短，$|a|$ 最小，答案選 (A)。"]], "tr": "把「值最小」想成「最左邊」而選 $|c|$；其實 $c$ 最小，但 $|c|$ 反而最大。"}, {"id": "111-2", "y": 111, "no": 2, "ch": "C06", "img": "img/hk/111_2.webp", "gimg": null, "a": 3, "rate": 0.82, "t": "多項式除法的餘式", "c": "除式是二次式時，餘式的次數必須比二次低，$4x$ 已經除不下去，就是餘式。", "st": [["先除最高次項", "多項式除法跟長除法一樣，從最高次項開始除。<br><br>$6x^2\\div 2x^2=3$，商先寫 $3$，再算 $3\\times 2x^2=6x^2$。"], ["相減得到餘式", "$(6x^2+4x)-6x^2=4x$。<br><br>$4x$ 是一次式，比除式 $2x^2$ 的次數（二次）還低，不能再除了，所以餘式是 $4x$。<br><br>$$6x^2+4x=2x^2\\times 3+4x$$<br><br>答案選 (D)。"]], "tr": "把 $4x\\div 2x^2$ 硬算成 $\\frac{2}{x}$ 或誤以為餘式是 $2$；餘式次數只要比除式低就停。"}, {"id": "111-3", "y": 111, "no": 3, "ch": "C02", "img": "img/hk/111_3.webp", "gimg": null, "a": 2, "rate": 0.8, "t": "找出 156 的質因數", "c": "質因數必須同時是「質數」又是「因數」；先做質因數分解再對選項。", "st": [["做質因數分解", "用短除法一路除小質數：<br><br>$156=2\\times 78=2\\times 2\\times 39=2\\times 2\\times 3\\times 13$<br><br>所以 $156=2^2\\times 3\\times 13$，質因數只有 $2$、$3$、$13$。"], ["逐一檢查選項", "- <b>(A) 錯誤</b>：$11$ 是質數，但 $156\\div 11$ 除不盡，不是因數。<br>- <b>(B) 錯誤</b>：$12$ 是因數，但 $12=2^2\\times 3$ 不是質數。<br>- <b>(C) 正確</b>：$13$ 是質數，也是 $156$ 的因數。<br>- <b>(D) 錯誤</b>：$14$ 不是質數，而且 $156\\div 14$ 也除不盡。"]], "tr": "看到 $12$ 能整除 $156$ 就選 (B)，忘了質因數還必須是質數。"}, {"id": "111-4", "y": 111, "no": 4, "ch": "C16", "img": "img/hk/111_4.webp", "gimg": null, "a": 1, "rate": 0.78, "t": "展開圖求長方體體積", "c": "從展開圖找出「底邊長」與「高」：四個側面寬都等於底邊，上下兩個底面加一個高等於 22。", "st": [["設未知數", "底面是正方形，設邊長為 $a$，長方體的高為 $h$。<br><br>展開圖中間那一排是 4 個側面，每個側面的寬都是底邊 $a$。"], ["由 12 求底邊", "標示 12 的地方跨過右邊 3 個側面，所以<br><br>$$3a=12\\Rightarrow a=4$$"], ["由 22 求高", "左邊那一直排由「底面＋側面＋底面」組成，長度是 $a+h+a$：<br><br>$$2a+h=22\\Rightarrow h=22-8=14$$<br><br>體積 $=a\\times a\\times h=4\\times 4\\times 14=224$，答案選 (B)。"]], "tr": "把 12 當成 4 個側面（得 $a=3$），或把 22 直接當成高。"}, {"id": "111-5", "y": 111, "no": 5, "ch": "C01", "img": "img/hk/111_5.webp", "gimg": null, "a": 0, "rate": 0.81, "t": "分數加減先分組", "c": "去括號後把分母相同的放在一起算，比通分全部四個分數快很多。", "st": [["去括號要變號", "括號前面是減號，拆開時裡面每一項都要變號：<br><br>$$\\frac{9}{22}+\\frac{11}{18}-\\frac{23}{22}+\\frac{7}{18}$$"], ["同分母的湊一起", "分母 22 的一組、分母 18 的一組：<br><br>$$\\left(\\frac{9}{22}-\\frac{23}{22}\\right)+\\left(\\frac{11}{18}+\\frac{7}{18}\\right)=-\\frac{14}{22}+\\frac{18}{18}=-\\frac{7}{11}+1=\\frac{4}{11}$$<br><br>答案選 (A)。"]], "tr": "去括號時忘了把 $-\\frac{7}{18}$ 變成 $+\\frac{7}{18}$，會算成 $-\\frac{7}{11}+\\frac{4}{18}$。"}, {"id": "111-6", "y": 111, "no": 6, "ch": "C07", "img": "img/hk/111_6.webp", "gimg": null, "a": 3, "rate": 0.75, "t": "估計根號 2022 的範圍", "c": "找兩個相鄰的完全平方數把 2022 夾在中間。", "st": [["找夾住它的平方數", "要估 $\\sqrt{2022}$，就找哪個數的平方接近 2022：<br><br>$40^2=1600$，$45^2=2025$。"], ["比較大小", "因為 $1600\\lt 2022\\lt 2025$，開根號後大小順序不變：<br><br>$$40\\lt \\sqrt{2022}\\lt 45$$<br><br>答案選 (D)。（其實 $\\sqrt{2022}$ 非常接近 45，只差一點點。）"]], "tr": "以為 $45^2$ 比 2022 小很多而選 (B)/(C)；記住 $45^2=2025$ 這個常考數字。"}, {"id": "111-7", "y": 111, "no": 7, "ch": "C04", "img": "img/hk/111_7.webp", "gimg": null, "a": 3, "rate": 0.69, "t": "點到鉛直線的距離", "c": "$x=-2$ 是一條鉛直線，點到它的距離就是兩者 $x$ 坐標相減的絕對值。", "st": [["認出直線的樣子", "$x=-2$ 表示所有 $x$ 坐標都是 $-2$ 的點，畫出來是一條鉛直線。<br><br>點到鉛直線的最短距離是「水平方向」走過去的長度。"], ["算水平距離", "$A(6,5)$ 的 $x$ 坐標是 6，直線的 $x$ 坐標是 $-2$：<br><br>$$|6-(-2)|=8$$<br><br>答案選 (D)。$y$ 坐標 5 在這題用不到。"]], "tr": "算成 $6-2=4$（忘了負號），或把 $y$ 坐標 5 也拿來用。"}, {"id": "111-8", "y": 111, "no": 8, "ch": "C06", "img": "img/hk/111_8.webp", "gimg": null, "a": 0, "rate": 0.71, "t": "十字交乘找係數", "c": "用十字交乘把 $39x^2+5x-14$ 拆成 $(3x+a)(bx+c)$，再代入求值。", "st": [["先決定 b", "展開後 $x^2$ 的係數是 $3b$，要等於 39，所以 $b=13$。<br><br>接著要找 $a$、$c$ 使 $ac=-14$，而且交叉相乘的和 $3c+13a=5$。"], ["試出 a、c", "$-14$ 的拆法有 $1\\times(-14)$、$2\\times(-7)$、$(-2)\\times 7$……逐一試：<br><br>$a=2$、$c=-7$：$3\\times(-7)+13\\times 2=-21+26=5$，成立！<br><br>所以 $39x^2+5x-14=(3x+2)(13x-7)$。"], ["代入所求", "$$a+2c=2+2\\times(-7)=-12$$<br><br>答案選 (A)。"]], "tr": "交叉相乘時把 $a$、$c$ 的位置配錯（算成 $3a+13c$），得到 $a=-7$、$c=2$ 而選錯。"}, {"id": "111-9", "y": 111, "no": 9, "ch": "C16", "img": "img/hk/111_9.webp", "gimg": null, "a": 2, "rate": 0.73, "t": "抽球號碼相同的機率", "c": "先列出箱子裡「剩下」的球，再數有幾顆的號碼出現在小茹抽過的號碼中。", "st": [["列出剩下的球", "原本 1～6 各 2 顆，小茹拿走 1、2、2、3、5。<br><br>剩下 7 顆：$1,3,4,4,5,6,6$（號碼 2 已經被拿光了）。"], ["數符合的球", "小茹抽過的號碼是 1、2、3、5。剩下的球中號碼是 1、3、5 的各一顆，共 3 顆。<br><br>每顆被抽中的機會相等，所以機率 $=\\frac{3}{7}$，答案選 (C)。"]], "tr": "分母用 6（號碼種類）或 12（原本總數）；要用剩下的 7 顆。也容易忘記號碼 2 已經沒有了。"}, {"id": "111-10", "y": 111, "no": 10, "ch": "C08", "img": "img/hk/111_10.webp", "gimg": null, "a": 2, "rate": 0.64, "t": "開平方解二次方程式", "c": "$(x-2)^2=3$ 直接開平方：$x-2=\\pm\\sqrt{3}$。", "st": [["直接開平方", "左邊已經是完全平方，不必展開。平方等於 3 的數有正負兩個：<br><br>$$x-2=\\sqrt{3}\\ \\text{或}\\ x-2=-\\sqrt{3}$$<br><br>所以 $x=2+\\sqrt{3}$ 或 $x=2-\\sqrt{3}$。"], ["分出大小再代入", "$a\\gt b$，所以 $a=2+\\sqrt{3}$，$b=2-\\sqrt{3}$。<br><br>$$2a+b=4+2\\sqrt{3}+2-\\sqrt{3}=6+\\sqrt{3}$$<br><br>答案選 (C)。"]], "tr": "只取正根、或把 $a$、$b$ 對調而算出 $6-\\sqrt{3}$。"}, {"id": "111-11", "y": 111, "no": 11, "ch": "C03", "img": "img/hk/111_11.webp", "gimg": null, "a": 2, "rate": 0.7, "t": "打折前後的預算", "c": "設預算為 $x$，用「售價 $=x+1200$」和「八折後 $=x-200$」列一元一次方程式。", "st": [["把對話翻成算式", "設哥哥的預算為 $x$ 元。<br><br>- 售價比預算多 1200 元：售價 $=x+1200$。<br>- 打 8 折後比預算少 200 元：$0.8\\times$ 售價 $=x-200$。"], ["列式求解", "$$0.8(x+1200)=x-200$$<br>$$0.8x+960=x-200$$<br>$$1160=0.2x\\Rightarrow x=5800$$<br><br>驗算：售價 7000 元，打八折 5600 元，比 5800 少 200 元，正確。答案選 (C)。"]], "tr": "把「打 8 折」算成減 8% 或減 20 元；8 折是乘以 $0.8$。"}, {"id": "111-12", "y": 111, "no": 12, "ch": "C01", "img": "img/hk/111_12.webp", "gimg": null, "a": 1, "rate": 0.64, "t": "科學記號的大小", "c": "$10^{-6}$ 表示小數點往左移 6 位，數字很小但仍是正數。", "st": [["還原成小數", "乘以 $10^{-6}$ 就是把小數點往左移 6 位：<br><br>$$7.52\\times 10^{-6}=0.00000752$$"], ["判斷位置", "它是正數，所以大於 0；又遠小於 0.5，所以在 0 與 1 之間而且非常接近 0。<br><br>答案選 (B)。"]], "tr": "看到負指數就以為整個數是負的，而選 (A)。"}, {"id": "111-13", "y": 111, "no": 13, "ch": "C14", "img": "img/hk/111_13.webp", "gimg": null, "a": 3, "rate": 0.56, "t": "弦心距與弦上一點", "c": "圓心到弦的垂足 $M$ 是弦的中點，再用畢氏定理算 $\\overline{OC}$。", "st": [["作弦心距找中點", "從 $O$ 作 $\\overline{AB}$ 的垂線，垂足為 $M$，則 $\\overline{OM}=3$。<br><br>圓心到弦的垂線會平分弦，所以 $M$ 是中點：$\\overline{AB}=6+2=8$，$\\overline{AM}=4$。"], ["算 MC", "$C$ 在 $M$ 和 $B$ 之間：$\\overline{MC}=\\overline{AC}-\\overline{AM}=6-4=2$。"], ["畢氏定理", "$\\triangle OMC$ 是直角三角形（$\\angle OMC=90^\\circ$）：<br><br>$$\\overline{OC}=\\sqrt{3^2+2^2}=\\sqrt{13}$$<br><br>答案選 (D)。"]], "tr": "直接拿 $\\overline{AC}=6$ 或 $\\overline{BC}=2$ 當直角邊，忘了要先找弦的中點。"}, {"id": "111-14", "y": 111, "no": 14, "ch": "C16", "img": "img/hk/111_14.webp", "gimg": null, "a": 2, "rate": 0.74, "t": "直方圖低於平均的比例", "c": "把年薪 60 萬元以下的長條人數加起來，再除以總人數 750 萬。", "st": [["加總 60 萬以下的人數", "平均數 60 萬元剛好在一組的分界上，所以把 0～60 萬之間的 10 根長條全加起來（單位萬人）：<br><br>$$5+5+10+40+80+100+80+80+65+45=510$$"], ["換成百分率", "$$\\frac{510}{750}=0.68=68\\%$$<br><br>答案選 (C)。這也說明薪水分布右邊拖很長，平均數會被高薪拉高，大部分人其實低於平均。"]], "tr": "以為「低於平均數的一定剛好一半」而選 50%；平均數不等於中位數。"}, {"id": "111-15", "y": 111, "no": 15, "ch": "C11", "img": "img/hk/111_15.webp", "gimg": null, "a": 1, "rate": 0.53, "t": "中垂線與角的大小", "c": "中垂線上的點到兩端等距，得 $\\overline{EA}=\\overline{EB}$；再用外角性質把角都用 $\\angle B$ 表示。", "st": [["判斷∠1 與∠2", "$\\overline{DE}$ 是 $\\overline{AB}$ 的中垂線，$E$ 在中垂線上，所以 $\\overline{EA}=\\overline{EB}$。<br><br>$\\triangle EDB$ 和 $\\triangle EDA$ 中，$\\overline{DB}=\\overline{DA}$、$\\overline{DE}$ 共用、$\\angle EDB=\\angle EDA=90^\\circ$，SAS 全等，所以 $\\angle 1=\\angle 2$。"], ["用 ∠B 表示各角", "設 $\\angle B=\\angle C=x^\\circ$。<br><br>- $\\triangle BDE$ 中：$\\angle 1=90^\\circ-x^\\circ$。<br>- $\\overline{EA}=\\overline{EB}$，所以 $\\angle EAB=\\angle B=x^\\circ$；$\\angle 3$ 是 $\\triangle ABE$ 的外角，$\\angle 3=x^\\circ+x^\\circ=2x^\\circ$。"], ["用 ∠EAC&gt;90° 比大小", "$\\triangle AEC$ 中，$\\angle EAC=180^\\circ-2x^\\circ-x^\\circ=180^\\circ-3x^\\circ\\gt 90^\\circ$，得 $x\\lt 30$。<br><br>所以 $\\angle 1=90-x\\gt 60$，$\\angle 3=2x\\lt 60$，即 $\\angle 1\\gt \\angle 3$。答案選 (B)。"]], "tr": "只看圖覺得 $\\angle 3$ 比較大；圖不一定照比例，要用 $\\angle EAC\\gt 90^\\circ$ 推出 $x\\lt 30$。"}, {"id": "111-16", "y": 111, "no": 16, "ch": "C03", "img": "img/hk/111_16.webp", "gimg": null, "a": 0, "rate": 0.55, "t": "緩降機需要的繩長", "c": "繩長 $=$ 樓板離地高度 $+$ 主體高出樓板的部分 $-$ 安全帶離地的 0.5 公尺。", "st": [["看懂示意圖", "緩降機主體掛在落地架上：落地架高出樓板 1.6 公尺，主體又在架頂下方 0.4 公尺，所以主體比樓板高 $1.6-0.4=1.2$ 公尺。<br><br>繩子下端的安全帶離一樓地面 0.5 公尺。"], ["算八樓樓板高度", "八樓的地板下面有一樓到七樓共 7 層，每層 3 公尺：<br><br>$$7\\times 3=21\\text{ 公尺}$$"], ["組合出繩長", "繩長 $=21+1.2-0.5=21.7$ 公尺，答案選 (A)。<br><br>（用三樓檢查：$2\\times 3+1.2-0.5=6.7$，和圖的結構相符。）"]], "tr": "八樓算成 $8\\times 3=24$ 公尺，或把 1.6 和 0.4 直接相加。"}, {"id": "111-17", "y": 111, "no": 17, "ch": "C12", "img": "img/hk/111_17.webp", "gimg": null, "a": 0, "rate": 0.49, "t": "平行線截角求內角", "c": "兩直線平行時，同側內角互補；分別求出 $\\angle C$、$\\angle A$，再用內角和。", "st": [["由 L∥BC 求 ∠C", "$\\overline{AC}$ 是截線，$L\\parallel\\overline{BC}$。$120^\\circ$ 這個角和 $\\angle C$ 都夾在兩平行線之間、在截線同一側，是同側內角，相加 $180^\\circ$：<br><br>$$\\angle C=180^\\circ-120^\\circ=60^\\circ$$"], ["由 M∥AB 求 ∠A", "同樣以 $\\overline{AC}$ 為截線，$M\\parallel\\overline{AB}$，$115^\\circ$ 和 $\\angle A$ 是同側內角：<br><br>$$\\angle A=180^\\circ-115^\\circ=65^\\circ$$"], ["三角形內角和", "$$\\angle B=180^\\circ-60^\\circ-65^\\circ=55^\\circ$$<br><br>答案選 (A)。"]], "tr": "把 $120^\\circ$ 當成和 $\\angle C$ 相等的同位角，直接得 $\\angle C=120^\\circ$ 就卡住了。"}, {"id": "111-18", "y": 111, "no": 18, "ch": "C03", "img": "img/hk/111_18.webp", "gimg": null, "a": 1, "rate": 0.51, "t": "折價券與第二雙六折", "c": "兩種付法相減得 $0.2\\times$（兩雙定價差），所以差價 50 元反推定價差 250 元。", "st": [["設定價列兩種花費", "設較貴那雙定價 $M$ 元，較便宜那雙 $m$ 元（$M\\ge m$）。<br><br>- 用折價券：兩雙都打 8 折，花 $0.8M+0.8m$。<br>- 參加活動：便宜那雙打 6 折，花 $M+0.6m$。"], ["相減比較", "$$(M+0.6m)-(0.8M+0.8m)=0.2M-0.2m=0.2(M-m)\\ge 0$$<br><br>所以參加活動花得比較多，<b>用折價券比較省</b>。"], ["由差 50 元求定價差", "$$0.2(M-m)=50\\Rightarrow M-m=250$$<br><br>兩雙定價相差 250 元，答案選 (B)。"]], "tr": "直覺以為「六折比八折便宜」就選參加活動，忘了活動只有一雙打折。"}, {"id": "111-19", "y": 111, "no": 19, "ch": "C15", "img": "img/hk/111_19.webp", "gimg": null, "a": 1, "rate": 0.5, "t": "重心與切線夾角", "c": "重心把中線分成 $2:1$，$\\overline{AG}=2\\overline{GD}=2$ 倍半徑，切線直角三角形變成 $30^\\circ$-$60^\\circ$-$90^\\circ$。", "st": [["重心性質", "$G$ 是重心，$\\overline{AD}$ 是中線，所以 $\\overline{AG}:\\overline{GD}=2:1$。<br><br>圓的半徑 $r=\\overline{GD}$，因此 $\\overline{AG}=2r$。"], ["切線直角三角形", "切線垂直半徑，$\\angle AEG=90^\\circ$，且 $\\overline{GE}=r$、斜邊 $\\overline{AG}=2r$。<br><br>斜邊是一股的兩倍，這是 $30^\\circ$-$60^\\circ$-$90^\\circ$ 三角形，所以 $\\angle GAE=30^\\circ$；同理 $\\angle GAF=30^\\circ$，$\\angle EAF=60^\\circ$。"], ["扣掉求 ∠1+∠2", "$\\angle BAC=180^\\circ-40^\\circ-45^\\circ=95^\\circ$。<br><br>$$\\angle 1+\\angle 2=95^\\circ-60^\\circ=35^\\circ$$<br><br>答案選 (B)。"]], "tr": "沒想到用重心 $2:1$，或把 $\\angle EAF$ 當成 $30^\\circ$（只算一邊）。"}, {"id": "111-20", "y": 111, "no": 20, "ch": "C13", "img": "img/hk/111_20.webp", "gimg": null, "a": 2, "rate": 0.5, "t": "正三角形摺紙求線段", "c": "摺過去的 $\\angle B$ 仍是 $60^\\circ$，與 $\\angle A$ 加上對頂角，得 $\\triangle ADF\\sim\\triangle BGF$。", "st": [["先求正三角形邊長", "摺紙前後 $\\overline{DB}$ 長度不變，摺後 $\\overline{DB}=\\overline{DF}+\\overline{FB}=14+8=22$。<br><br>所以邊長 $\\overline{AB}=\\overline{AD}+\\overline{DB}=10+22=32$，$\\overline{FC}=32-16=16$。"], ["找相似三角形", "$\\triangle ADF$ 與 $\\triangle BGF$（$B$ 指摺過去的位置）中：<br><br>- $\\angle A=60^\\circ$，摺過去的 $\\angle B$ 也還是 $60^\\circ$；<br>- $\\angle AFD=\\angle BFG$（對頂角）。<br><br>AA 相似，$\\triangle ADF\\sim\\triangle BGF$，對應邊 $A\\leftrightarrow B$、$D\\leftrightarrow G$、$F\\leftrightarrow F$。"], ["由比例算 FG", "$$\\frac{\\overline{GF}}{\\overline{DF}}=\\frac{\\overline{BF}}{\\overline{AF}}=\\frac{8}{16}=\\frac{1}{2}\\Rightarrow\\overline{GF}=7$$<br><br>$$\\overline{CG}=\\overline{FC}-\\overline{GF}=16-7=9$$<br><br>答案選 (C)。"]], "tr": "相似的對應邊配錯（把 $\\overline{GF}$ 對到 $\\overline{AF}$），或忘了先算邊長 32。"}, {"id": "111-21", "y": 111, "no": 21, "ch": "C14", "img": "img/hk/111_21.webp", "gimg": null, "a": 1, "rate": 0.41, "t": "直徑上的弧長關係", "c": "直徑所對的圓周角是直角；等長的弦對應等長的弧，用畢氏定理比較弦長。", "st": [["直角三角形算弦長", "$\\overline{AB}$ 是直徑，所以 $\\angle ACB=\\angle ADB=\\angle AEB=\\angle AFB=90^\\circ$。用畢氏定理：<br><br>- $\\overline{BC}=\\sqrt{10^2-6^2}=8$，$\\overline{BD}=\\sqrt{10^2-8^2}=6$<br>- $\\overline{BE}=\\sqrt{10^2-5^2}=\\sqrt{75}$，$\\overline{BF}=\\sqrt{10^2-9^2}=\\sqrt{19}$"], ["判斷上半圓", "$C$ 在上半圓，$\\overset{\\frown}{AC}+\\overset{\\frown}{CB}=\\overset{\\frown}{AB}$（半圓）。<br><br>$\\overline{CB}=8=\\overline{AD}$，等弦對等弧，$\\overset{\\frown}{CB}=\\overset{\\frown}{AD}$，所以 $\\overset{\\frown}{AC}+\\overset{\\frown}{AD}=\\overset{\\frown}{AB}$ 成立。"], ["判斷下半圓", "同理要 $\\overset{\\frown}{AE}+\\overset{\\frown}{AF}=\\overset{\\frown}{AB}$，必須 $\\overset{\\frown}{AF}=\\overset{\\frown}{EB}$，也就是 $\\overline{AF}=\\overline{EB}$。<br><br>但 $\\overline{AF}=9=\\sqrt{81}\\neq\\sqrt{75}=\\overline{EB}$，所以不相等。答案選 (B)。<br><br>（快解：弦長平方相加 $=100$ 的兩條才配成一對，$6^2+8^2=100$，$5^2+9^2=106\\neq 100$。）"]], "tr": "以為 $6+8$ 不等於 10 所以不成立；弧長不能用弦長直接相加。"}, {"id": "111-22", "y": 111, "no": 22, "ch": "C10", "img": "img/hk/111_22.webp", "gimg": null, "a": 0, "rate": 0.4, "t": "拋物線上移後的交點", "c": "上下平移對稱軸不變，所以兩交點的中點不變；開口向下的圖形往上移，與 $x$ 軸的交點會越分越開。", "st": [["比較兩根的和", "$y=-(x+6)^2+5$ 的對稱軸是 $x=-6$，往上平移對稱軸不變。<br><br>和 $x$ 軸的兩交點對稱於 $x=-6$，所以 $\\frac{a+b}{2}=-6=\\frac{c+d}{2}$，得 $a+b=c+d=-12$。"], ["比較兩根的距離", "圖形開口向下、頂點在 $x$ 軸上方。往上平移後頂點更高，拋物線在 $x$ 軸上方的部分變寬，兩交點距離變大：<br><br>$$b-a\\lt d-c$$<br><br>例如原本 $(x+6)^2=5$，$b-a=2\\sqrt{5}$；上移 4 後 $(x+6)^2=9$，$d-c=6\\gt 2\\sqrt{5}$。答案選 (A)。"]], "tr": "以為平移後交點也跟著左右移而選 (C)/(D)；上下平移不改變對稱軸。"}, {"id": "111-23", "y": 111, "no": 23, "ch": "C13", "img": "img/hk/111_23.webp", "gimg": null, "a": 3, "rate": 0.33, "t": "兩組相似求面積比", "c": "由 $\\triangle FAC\\sim\\triangle ABC$ 求出 $\\overline{AC}$，再由 $\\triangle BED\\sim\\triangle BAC$ 得兩塊面積，大三角形扣掉即可。", "st": [["第一組相似求 AC", "$\\angle FAC=\\angle B$，$\\angle C$ 共用，所以 $\\triangle FAC\\sim\\triangle ABC$（$F\\leftrightarrow A$、$A\\leftrightarrow B$、$C\\leftrightarrow C$）。<br><br>$$\\frac{\\overline{CF}}{\\overline{CA}}=\\frac{\\overline{CA}}{\\overline{CB}}\\Rightarrow\\overline{CA}^2=5\\times 16=80$$<br><br>面積比 $\\triangle FAC:\\triangle ABC=\\overline{CA}^2:\\overline{CB}^2=80:256=5:16$。"], ["第二組相似", "$\\angle BDE=\\angle C$，$\\angle B$ 共用，所以 $\\triangle BDE\\sim\\triangle BCA$（$D\\leftrightarrow C$、$E\\leftrightarrow A$）。<br><br>相似比 $=\\overline{BD}:\\overline{BC}=\\overline{AC}:\\overline{BC}$，面積比 $=\\overline{BD}^2:\\overline{BC}^2=80:256=5:16$。"], ["扣掉求四邊形", "把 $\\triangle ABC$ 面積看成 16 份，兩個小三角形各 5 份：<br><br>$$ADEF=16-5-5=6\\text{ 份}$$<br><br>$ADEF:\\triangle ABC=6:16=3:8$，答案選 (D)。"]], "tr": "相似三角形對應頂點寫錯；或把面積比當成邊長比（沒有平方）。"}, {"id": "111-24", "y": 111, "no": 24, "ch": "C05", "img": "img/hk/111_24.webp", "gimg": "img/hk/111_G24.webp", "a": 3, "rate": 0.44, "t": "比較燈管發光效率", "c": "發光效率 $=$ 光通量 $\\div$ 功率，逐一算出比值再比較。", "st": [["判斷甲", "算「每瓦能發多少流明」：<br><br>- PA-20：$1440\\div 20=72$<br>- PB-14：$1200\\div 14\\approx 85.7$<br><br>PA-20 比較低，<b>甲錯誤</b>。"], ["判斷乙", "PA 三種：<br><br>- PA-20：$72$<br>- PA-30：$2340\\div 30=78$<br>- PA-40：$3360\\div 40=84$<br><br>功率越大，效率越高，<b>乙正確</b>。答案選 (D)。"]], "tr": "只看光通量 $1440\\gt 1200$ 就說 PA-20 較好；要比的是「比值」不是光通量本身。"}, {"id": "111-25", "y": 111, "no": 25, "ch": "C03", "img": "img/hk/111_25.webp", "gimg": "img/hk/111_G24.webp", "a": 3, "rate": 0.42, "t": "省電方案多久回本", "c": "每小時省下的電費 $\\times t\\gt $ 施工費差 15000 元，解一元一次不等式。", "st": [["每小時用電差多少", "基本方案：$90\\times 40=3600$ 瓦；省電方案：$120\\times 28=3360$ 瓦。<br><br>每小時少用 $3600-3360=240$ 瓦，用公式換成度：$\\frac{240}{1000}=0.24$ 度。"], ["每小時省多少錢", "每度 5 元，每小時省 $0.24\\times 5=1.2$ 元。<br><br>施工費差 $60000-45000=15000$ 元。"], ["列不等式", "使用 $t$ 小時後，省下的電費要超過 15000 元：<br><br>$$1.2t\\gt 15000\\Rightarrow t\\gt 12500$$<br><br>至少要超過 12500 小時，答案選 (D)。"]], "tr": "忘了把瓦換成度（沒有除以 1000），或只比較單支燈管 $40-28$ 而沒乘支數。"}, {"id": "112-1", "y": 112, "no": 1, "ch": "C01", "img": "img/hk/112_1.webp", "gimg": null, "a": 0, "rate": 0.89, "t": "負數的三次方", "c": "$(-3)^3$ 是三個 $-3$ 相乘，奇數個負數相乘結果是負的。", "st": [["把次方展開", "指數 3 的意思是「同一個數連乘 3 次」，所以<br>$$(-3)^3=(-3)\\times(-3)\\times(-3)$$"], ["先定正負再算大小", "三個負數相乘，負號有奇數個，結果是負的；數值部分 $3\\times3\\times3=27$。<br>$$(-3)^3=-27$$<br>答案選 (A)。"]], "tr": "把次方誤當乘法算成 $-3\\times3=-9$；或以為負數的次方一定是正的。偶數次方 $(-3)^2=9$ 才是正的。"}, {"id": "112-2", "y": 112, "no": 2, "ch": "C06", "img": "img/hk/112_2.webp", "gimg": null, "a": 2, "rate": 0.87, "t": "平方差公式找因式", "c": "$x^2-36=x^2-6^2$，用平方差公式 $a^2-b^2=(a+b)(a-b)$ 分解。", "st": [["看出平方差", "36 是 6 的平方，所以 $x^2-36$ 是「兩個平方相減」，正好可以用平方差公式：<br>$$x^2-36=x^2-6^2=(x+6)(x-6)$$"], ["對照選項", "因式是 $x+6$ 和 $x-6$，選項中只有 $x-6$ 出現，答案選 (C)。<br><br><b>檢查</b>：把 $x=6$ 代入 $x^2-36$ 得 0，表示 $x-6$ 確實是因式。"]], "tr": "把 36 誤當成 $9\\times4$ 而選 $x-9$ 或 $x-4$；平方差要找「平方數」6，不是隨便兩個乘起來是 36 的數。"}, {"id": "112-3", "y": 112, "no": 3, "ch": "C16", "img": "img/hk/112_3.webp", "gimg": null, "a": 1, "rate": 0.89, "t": "拿走積木看前視圖", "c": "前視圖只看每一個左右位置「最高疊到幾層」；被前後同一列其他積木擋住的方塊拿走不影響。", "st": [["前視圖看什麼", "從前面看時，前後排在同一條視線上的積木會重疊成一格。所以前視圖每一直行的高度＝那個左右位置上「最高的那一疊」。<br>拿走某個積木會讓前視圖改變，必須是：它所在的那一直行，<b>只有它撐到那個高度</b>。"], ["把圖(一)分成左右三行", "依箭頭方向（從左下往右上看），由左到右可看成三個左右位置：<br>- 左邊：最左的 3 層高柱子，以及它正後方同樣 3 層高、頂端是甲的柱子 → 高 3 層。<br>- 中間：乙所在的位置，乙在第 2 層，此位置最高只到乙 → 高 2 層。<br>- 右邊：丁那一排（丁和它後面的一個積木）→ 高 1 層。<br>所以前視圖像一個由左往右 3、2、1 的階梯。"], ["逐一判斷", "- <b>(A) 甲</b>：甲的前面有一樣高 3 層的柱子擋著，拿走甲，左行仍是 3 層，不變。<br>- <b>(B) 乙</b>：中間這行只有乙到第 2 層，拿走後這行變成 1 層，前視圖<b>改變</b>。<br>- <b>(C) 丙</b>：丙在最底層，同一行還有其他積木撐著，高度不變。<br>- <b>(D) 丁</b>：丁後面還有一個積木在同一條視線上，拿走丁，前視圖那一格仍在。<br><br>答案選 (B)。"]], "tr": "以為拿走最高的甲一定會改變；其實甲被前面的 3 層柱子遮住，前視圖看不出來少了它。"}, {"id": "112-4", "y": 112, "no": 4, "ch": "C07", "img": "img/hk/112_4.webp", "gimg": null, "a": 2, "rate": 0.8, "t": "根號化簡", "c": "把 135 分解成「最大平方數 × 剩下的數」，平方數開出根號外。", "st": [["質因數分解找平方", "化簡根號的目的是把能開方的「平方因數」拿到外面。<br>$$135=3^3\\times5=9\\times15$$<br>其中 $9=3^2$ 是平方數，15 裡面已經沒有平方因數了。"], ["開到根號外", "$$\\sqrt{135}=\\sqrt{9\\times15}=\\sqrt{9}\\times\\sqrt{15}=3\\sqrt{15}$$<br>答案選 (C)。<br><br><b>檢查</b>：$3\\sqrt{15}$ 平方 $=9\\times15=135$，正確。"]], "tr": "把 $135=27\\times5$ 直接寫成 $27\\sqrt5$，忘了 27 要開根號；27 也不是平方數。"}, {"id": "112-5", "y": 112, "no": 5, "ch": "C10", "img": "img/hk/112_5.webp", "gimg": null, "a": 1, "rate": 0.77, "t": "點是否在直線上", "c": "點在圖形上 ⇔ 點的坐標代入方程式會成立。", "st": [["代入 x 坐標", "四個選項的 $x$ 坐標都是 $-4$，所以把 $x=-4$ 代入，看 $y$ 應該是多少：<br>$$y=-2\\times(-4)-6=8-6=2$$"], ["找出對應的點", "圖形通過 $(-4,2)$，答案選 (B)。"]], "tr": "$-2\\times(-4)$ 算成 $-8$，得到 $y=-14$ 而找不到答案；負負得正要小心。"}, {"id": "112-6", "y": 112, "no": 6, "ch": "C01", "img": "img/hk/112_6.webp", "gimg": null, "a": 0, "rate": 0.77, "t": "負帶分數比大小", "c": "負數比大小：絕對值越大，數反而越小。", "st": [["先比絕對值", "負數的大小和絕對值相反，所以先比 $1$、$1\\frac{3}{4}$、$1\\frac{5}{8}$ 誰大。<br>通分成分母 8：$\\frac{3}{4}=\\frac{6}{8}\\gt \\frac{5}{8}$，所以<br>$$1\\lt 1\\frac{5}{8}\\lt 1\\frac{3}{4}$$"], ["變回負數順序反過來", "加上負號後大小順序顛倒：<br>$$-1\\gt -1\\frac{5}{8}\\gt -1\\frac{3}{4}$$<br>也就是 $a\\gt c\\gt b$，答案選 (A)。"]], "tr": "直接用絕對值排順序而選 (C) $b\\gt c\\gt a$；負數要反過來。"}, {"id": "112-7", "y": 112, "no": 7, "ch": "C04", "img": "img/hk/112_7.webp", "gimg": null, "a": 0, "rate": 0.7, "t": "鉛直線水平線分區域", "c": "在鉛直線 $x=-5$ 左邊的點 $x\\lt -5$；在水平線 $y=-3$ 上方的點 $y\\gt -3$。", "st": [["看 P 和 L 的位置", "直線 $L$：$x=-5$ 是一條鉛直線，線上每一點的 $x$ 坐標都是 $-5$。<br>$P$ 在 $L$ 的<b>左邊</b>（緊貼著 $L$ 但在左側），越往左 $x$ 越小，所以 $a\\lt -5$。"], ["看 P 和 M 的位置", "直線 $M$：$y=-3$ 是一條水平線，線上每一點的 $y$ 坐標都是 $-3$。<br>$P$ 在 $M$ 的<b>上方</b>，越往上 $y$ 越大，所以 $b\\gt -3$。<br><br>答案選 (A)。"]], "tr": "$P$ 離 $L$ 很近，沒看清楚是在左側還是右側；也有人拿 $P$ 和坐標軸比，要比的是和直線 $L$、$M$ 的相對位置。"}, {"id": "112-8", "y": 112, "no": 8, "ch": "C12", "img": "img/hk/112_8.webp", "gimg": null, "a": 2, "rate": 0.7, "t": "梯形同側內角互補", "c": "$\\overline{AD}\\parallel\\overline{BC}$，同側內角 $\\angle ADC+\\angle C=180^\\circ$。", "st": [["用平行線求 ∠C", "因為 $\\overline{AD}\\parallel\\overline{BC}$，$\\overline{CD}$ 是截線，同側內角互補：<br>$$\\angle C=180^\\circ-140^\\circ=40^\\circ$$"], ["在直角三角形中求 ∠DBC", "$\\overline{BD}\\perp\\overline{CD}$，所以 $\\triangle BCD$ 中 $\\angle BDC=90^\\circ$。三角形內角和 $180^\\circ$：<br>$$\\angle DBC=180^\\circ-90^\\circ-40^\\circ=50^\\circ$$<br>答案選 (C)。"]], "tr": "以為 $\\angle ADB=90^\\circ$ 而用 $140^\\circ-90^\\circ=50^\\circ$ 碰巧對，但推理錯；直角在 $\\angle BDC$。"}, {"id": "112-9", "y": 112, "no": 9, "ch": "C02", "img": "img/hk/112_9.webp", "gimg": null, "a": 1, "rate": 0.72, "t": "既是倍數又是因數", "c": "18 的倍數且是 216 的因數，就是 $18\\times k$ 且 $k$ 是 $216\\div18=12$ 的因數。", "st": [["轉成找 12 的因數", "這個數要是 18 的倍數，寫成 $18k$（$k$ 是正整數）。<br>它又要整除 216，而 $216=18\\times12$，所以 $18k$ 整除 $18\\times12$，等於 $k$ 整除 12。"], ["數 12 的因數", "12 的正因數：1、2、3、4、6、12，共 6 個。<br>對應的數是 18、36、54、72、108、216，共 6 個，答案選 (B)。"]], "tr": "漏掉 18 本身或 216 本身；一個數是自己的倍數，也是自己的因數。"}, {"id": "112-10", "y": 112, "no": 10, "ch": "C08", "img": "img/hk/112_10.webp", "gimg": null, "a": 3, "rate": 0.58, "t": "公式解求較大根", "c": "$ax^2+bx+c=0$ 的解 $x=\\dfrac{-b\\pm\\sqrt{b^2-4ac}}{2a}$，取「＋」得較大的解。", "st": [["找出 a、b、c", "$3x^2-11x-1=0$ 中，$a=3$、$b=-11$、$c=-1$。注意 $b$ 和 $c$ 都是負的。"], ["算根號裡面", "$$b^2-4ac=(-11)^2-4\\times3\\times(-1)=121+12=133$$"], ["代公式取較大值", "$$x=\\frac{-(-11)\\pm\\sqrt{133}}{2\\times3}=\\frac{11\\pm\\sqrt{133}}{6}$$<br>$a\\gt b$，$a$ 是用「＋」的那個：$a=\\dfrac{11+\\sqrt{133}}{6}$，答案選 (D)。"]], "tr": "$-4\\times3\\times(-1)$ 算成 $-12$ 得到 109；或忘了 $-b=11$ 而寫成 $-11$。"}, {"id": "112-11", "y": 112, "no": 11, "ch": "C05", "img": "img/hk/112_11.webp", "gimg": null, "a": 3, "rate": 0.66, "t": "咖啡因含量範圍判斷", "c": "每毫升含量相同 → 咖啡因與容量成正比；用中杯、大杯的顏色夾出兩杯中杯的範圍。", "st": [["由中杯得到上限", "中杯 360 毫升標黃色：咖啡因超過 100、不超過 200 毫克。<br>兩杯中杯是 720 毫升，恰好是 2 倍，所以兩杯的咖啡因 **不超過 $2\\times200=400$ 毫克**。"], ["由大杯得到下限", "大杯 480 毫升標紅色：超過 200 毫克。因為咖啡因和容量成正比，<br>$$720 \\text{ 毫升是 } 480 \\text{ 毫升的 } \\frac{720}{480}=\\frac{3}{2} \\text{ 倍}$$<br>所以兩杯中杯的咖啡因 **超過 $200\\times\\frac{3}{2}=300$ 毫克**。"], ["和建議值比較", "兩杯中杯的咖啡因介於「超過 300、不超過 400」毫克：<br>- 我國建議不超過 300 → 一定超過，<b>不符合</b>。<br>- 歐盟建議不超過 400 → 一定不超過，<b>符合</b>。<br><br>答案選 (D)。"]], "tr": "只用中杯的黃色算出 200~400 毫克，以為無法判斷我國；要再利用大杯紅色的資訊把下限推到 300。"}, {"id": "112-12", "y": 112, "no": 12, "ch": "C16", "img": "img/hk/112_12.webp", "gimg": null, "a": 0, "rate": 0.58, "t": "兩盒盒玩都喜歡的機率", "c": "兩盒結果互不影響，機率相乘：$\\frac{2}{6}\\times\\frac{1}{5}$。", "st": [["分別算兩盒的機率", "動物系列 6 款機會相等，喜歡的有 A、C 兩款：機率 $\\frac{2}{6}=\\frac{1}{3}$。<br>汽車系列 5 款機會相等，喜歡的只有 B 款：機率 $\\frac{1}{5}$。"], ["兩件事都要發生就相乘", "也可以想成所有結果共 $6\\times5=30$ 種，兩盒都喜歡的有 $2\\times1=2$ 種：<br>$$\\frac{2}{30}=\\frac{1}{15}$$<br>答案選 (A)。"]], "tr": "把兩個機率相加；或把 11 款混在一起算成 $\\frac{3}{11}$。兩盒是分開抽的。"}, {"id": "112-13", "y": 112, "no": 13, "ch": "C11", "img": "img/hk/112_13.webp", "gimg": null, "a": 0, "rate": 0.5, "t": "直角柱中的大邊對大角", "c": "同一個三角形中，大邊對大角；直角三角形中，較短股對的銳角小於 $45^\\circ$。", "st": [["比較 ∠ACB 與 ∠FDE", "直角柱上下底是全等三角形，$D$ 對 $A$、$E$ 對 $B$、$F$ 對 $C$，所以 $\\angle FDE=\\angle CAB$。<br>在 $\\triangle ABC$ 中，$\\overline{BC}\\gt \\overline{AB}$，大邊對大角：$\\angle CAB$（對 $\\overline{BC}$）$\\gt \\angle ACB$（對 $\\overline{AB}$）。<br>所以 $\\angle ACB\\lt \\angle FDE$。"], ["用 45° 當中間值", "- $\\triangle ABC$：$\\angle ACB+\\angle CAB=90^\\circ$ 且 $\\angle ACB$ 較小，所以 $\\angle ACB\\lt 45^\\circ$。<br>- 側面 $ABED$ 是長方形，$\\angle ABE=90^\\circ$。在 $\\triangle ABE$ 中 $\\overline{AB}\\gt \\overline{BE}$，所以 $\\angle AEB$（對 $\\overline{AB}$）$\\gt \\angle BAE$，兩角和 $90^\\circ$，故 $\\angle AEB\\gt 45^\\circ$。<br><br>因此 $\\angle AEB\\gt 45^\\circ\\gt \\angle ACB$，答案選 (A)。"]], "tr": "$\\angle AEB$ 和 $\\angle ACB$ 不在同一個三角形，不能直接用大邊對大角；要借 $45^\\circ$ 當橋梁。"}, {"id": "112-14", "y": 112, "no": 14, "ch": "C10", "img": "img/hk/112_14.webp", "gimg": null, "a": 1, "rate": 0.56, "t": "拋物線對稱軸求頂點距離", "c": "水平線和拋物線的兩交點對稱於對稱軸，頂點的 $x$ 坐標是兩交點的中點。", "st": [["弄清楚哪兩點同一條拋物線", "從圖看：頂點 $P$ 的拋物線交水平線於 $A$、$C$；頂點 $Q$ 的拋物線交水平線於 $B$、$D$。<br>把水平線當數線，令 $A$ 在 0，則 $B$ 在 10、$C$ 在 $15$、$D$ 在 $21$。"], ["用對稱求 P、Q", "拋物線左右對稱，頂點在兩交點正中間：<br>$$P \\text{ 的位置}=\\frac{0+15}{2}=7.5,\\quad Q \\text{ 的位置}=\\frac{10+21}{2}=15.5$$<br>$$\\overline{PQ}=15.5-7.5=8$$<br>答案選 (B)。"]], "tr": "誤以為 $A$、$B$ 是同一條拋物線的交點；看清楚圖中曲線，$A$、$C$ 一組，$B$、$D$ 一組。"}, {"id": "112-15", "y": 112, "no": 15, "ch": "C09", "img": "img/hk/112_15.webp", "gimg": null, "a": 3, "rate": 0.42, "t": "插入數後的等差數列項數", "c": "原本相鄰兩項差 1 要被新公差平分，每段插入相同個數，項數 $=4m+1$。", "st": [["新公差要整除 1", "新數列仍含 1、2、3、4、5（題意是在原數列中「插入」），所以相鄰兩原項之間要插入<b>一樣多</b>個數，才能維持等差。<br>設每兩個原項之間插入 $m-1$ 個數，那麼每一段被分成 $m$ 等分，新公差是 $\\frac{1}{m}$。"], ["算項數", "從 1 到 5 共 4 段，每段 $m$ 個公差，共 $4m$ 個公差，所以項數<br>$$n=4m+1$$<br>也就是 $n-1$ 必須是 4 的倍數。"], ["檢查選項", "- <b>(A) 11</b>：$10$ 不是 4 的倍數。<br>- <b>(B) 15</b>：$14$ 不是 4 的倍數。<br>- <b>(C) 30</b>：$29$ 不是 4 的倍數。<br>- <b>(D) 33</b>：$32=4\\times8$ ✓，每段插入 7 個數，公差 $\\frac{1}{8}$。<br><br>答案選 (D)。"]], "tr": "只想到首末項是 1、5 而用 $n-1$ 整除 4，忽略原來的 2、3、4 也要留在數列中，必須每段等分。"}, {"id": "112-16", "y": 112, "no": 16, "ch": "C04", "img": "img/hk/112_16.webp", "gimg": null, "a": 2, "rate": 0.5, "t": "套餐與單點的價格關係", "c": "設雞排 $x$、可樂 $y$，套餐 $x+y-40$；把兩個條件列成方程式化簡。", "st": [["設未知數", "設單點雞排 $x$ 元、單點可樂 $y$ 元。套餐比單點兩樣便宜 40 元，所以一份套餐 $=x+y-40$ 元。"], ["把促銷條件列式", "買一片雞排會送一片，所以「單點一片雞排＋兩杯可樂」就得到兩片雞排兩杯可樂，花 $x+2y$ 元，比兩份套餐便宜 10 元：<br>$$x+2y=2(x+y-40)-10$$"], ["化簡", "$$x+2y=2x+2y-90\\Rightarrow x=90$$<br>$y$ 被消掉了，表示可樂（以及套餐）的價錢無法確定，但雞排<b>一定</b>是 90 元。答案選 (C)。"]], "tr": "以為兩個未知數一定要兩個方程式才能解；本題只能確定雞排價格，套餐價錢跟著可樂變，所以 (A)(B) 都不必然。"}, {"id": "112-17", "y": 112, "no": 17, "ch": "C15", "img": "img/hk/112_17.webp", "gimg": null, "a": 3, "rate": 0.49, "t": "方格紙上找外心的圓", "c": "外心到三頂點等距，$B$、$C$ 都在以 $O$ 為圓心、$\\overline{OA}$ 為半徑的圓上，且必須是格子點。", "st": [["求外接圓半徑", "以方格紙左下角為原點，$O=(2,0)$、$A=(3,3)$。<br>$O$ 是外心，所以 $\\overline{OA}=\\overline{OB}=\\overline{OC}$：<br>$$\\overline{OA}=\\sqrt{1^2+3^2}=\\sqrt{10}$$"], ["找距離 O 為 √10 的格子點", "$\\sqrt{10}$ 只能由橫差、縱差為 1 和 3 組成（$1+9=10$）。在方格紙範圍內（$x$ 從 0 到 7、$y$ 從 0 到 4）符合的點只有<br>$$(1,3)、(3,3)、(5,1)$$<br>$(3,3)$ 就是 $A$，所以 $B$、$C$ 是 $(1,3)$ 和 $(5,1)$。"], ["算 BC", "$$\\overline{BC}=\\sqrt{(5-1)^2+(1-3)^2}=\\sqrt{16+4}=\\sqrt{20}$$<br>答案選 (D)。"]], "tr": "漏找 $(5,1)$ 這種「橫 3 縱 1」的點，或把方格紙外的點（如 $(-1,1)$）也算進去。"}, {"id": "112-18", "y": 112, "no": 18, "ch": "C03", "img": "img/hk/112_18.webp", "gimg": null, "a": 1, "rate": 0.43, "t": "分時段停車費", "c": "白天時段收費已達上限 100 元，晚上 $x-10$ 小時每小時 5 元，且不會超過 30 元上限。", "st": [["白天時段", "10:00 進場，到 20:00 共 10 小時，若按 20 元算是 200 元，但此時段最多收 100 元，所以白天收 <b>100 元</b>。"], ["晚上時段", "離場在 20:00～24:00 之間，晚上停了 $x-10$ 小時，最多 4 小時，費用 $5(x-10)\\le20$，沒有超過 30 元上限，照算：<br>$$5(x-10)=5x-50$$"], ["相加", "$$100+5x-50=5x+50$$<br>答案選 (B)。"]], "tr": "忘了白天有 100 元上限而算成 $200+5(x-10)=5x+150$；或晚上誤用 $5x$ 把白天時數也算進去。"}, {"id": "112-19", "y": 112, "no": 19, "ch": "C14", "img": "img/hk/112_19.webp", "gimg": null, "a": 1, "rate": 0.48, "t": "摺圓形紙片求弧度", "c": "摺疊前後對稱，$\\angle DAB=\\angle CAB$；把 $D$ 摺回原圓，用圓周角＝所對弧的一半。", "st": [["先求 ∠BAC", "$\\angle BAC$ 是圓周角，所對的弧是 $\\overset{\\frown}{BC}=35^\\circ$，所以<br>$$\\angle BAC=\\frac{35^\\circ}{2}=17.5^\\circ$$"], ["把 D 摺回去", "$\\overline{AB}$ 是摺線，摺疊前後圖形對稱。把 $D$ 摺回原來的圓上得到點 $D'$（在左側的 $\\overset{\\frown}{AB}$ 上），且 $\\angle D'AB=\\angle DAB=17.5^\\circ$。<br>圓周角 $\\angle D'AB$ 所對的弧 $\\overset{\\frown}{D'B}=2\\times17.5^\\circ=35^\\circ$。"], ["求 AD 弧", "$\\overline{AC}$ 是直徑，左側 $\\overset{\\frown}{AB}=180^\\circ-35^\\circ=145^\\circ$。<br>$$\\overset{\\frown}{AD}=\\overset{\\frown}{AD'}=145^\\circ-35^\\circ=110^\\circ$$<br>答案選 (B)。"]], "tr": "直接答 $\\overset{\\frown}{AB}=145^\\circ$（選 D），忘了要扣掉 $D$ 到 $B$ 的那一段弧。"}, {"id": "112-20", "y": 112, "no": 20, "ch": "C11", "img": "img/hk/112_20.webp", "gimg": null, "a": 2, "rate": 0.43, "t": "中垂線造出等腰三角形", "c": "中垂線上的點到線段兩端等距，$\\triangle EBD$、$\\triangle FDC$ 都是等腰三角形。", "st": [["中垂線帶出等腰", "$E$ 在 $\\overline{BD}$ 的中垂線上，所以 $\\overline{EB}=\\overline{ED}$，$\\angle EDB=\\angle B$。<br>同理 $F$ 在 $\\overline{CD}$ 的中垂線上，$\\overline{FD}=\\overline{FC}$，$\\angle FDC=\\angle C$。"], ["比較 ∠2 與 ∠4", "$\\angle 2$ 在平角 $\\angle BDC$ 上：<br>$$\\angle2=180^\\circ-\\angle EDB-\\angle FDC=180^\\circ-\\angle B-\\angle C=\\angle A=\\angle4$$"], ["比較 ∠1 與 ∠3", "$\\angle1$ 是 $\\triangle EBD$ 的外角，等於兩內對角和：$\\angle1=\\angle B+\\angle EDB=2\\angle B$。<br>同理 $\\angle3=2\\angle C$。三內角都不相等，$\\angle B\\neq\\angle C$，所以 $\\angle1\\neq\\angle3$。<br><br>答案選 (C)。"]], "tr": "看圖覺得左右對稱就選 (A)；題目特別說三內角不相等，圖只是示意。"}, {"id": "112-21", "y": 112, "no": 21, "ch": "C05", "img": "img/hk/112_21.webp", "gimg": null, "a": 3, "rate": 0.41, "t": "吊橋上兩人步數換算", "c": "同一段距離，小維 84 步＝阿良 70 步，得兩人步長比，再換算東段距離。", "st": [["找出兩人步長的關係", "交會點到西橋頭這一段：小維走了 84 步，阿良也走了 70 步，是同一段距離。<br>$$84 \\text{ 小維步}=70 \\text{ 阿良步}\\Rightarrow 1 \\text{ 阿良步}=\\frac{84}{70}=\\frac{6}{5} \\text{ 小維步}$$"], ["換算東段", "交會點到東橋頭這一段，阿良走了 60 步，換成小維的步數：<br>$$60\\times\\frac{6}{5}=72 \\text{ 步}$$<br>答案選 (D)。"]], "tr": "把比例倒過來算成 $60\\times\\frac{5}{6}=50$（選 B）；阿良步子比較大，小維要走更多步。"}, {"id": "112-22", "y": 112, "no": 22, "ch": "C13", "img": "img/hk/112_22.webp", "gimg": null, "a": 2, "rate": 0.27, "t": "由面積求高再求線段比", "c": "$\\triangle EBG=\\triangle EBC-\\triangle GBC$ 求出 $E$ 的高；$\\triangle EFG\\sim\\triangle EBC$，邊長比＝高的比。", "st": [["用面積求 E 的高", "正方形面積 16，邊長 4。設 $E$ 到 $\\overline{BC}$ 的距離為 $h$。<br>$G$ 在 $\\overline{AD}$ 上，到 $\\overline{BC}$ 距離 4，所以<br>$$\\triangle EBG=\\triangle EBC-\\triangle GBC=\\frac{4h}{2}-\\frac{4\\times4}{2}=2h-8$$<br>$2h-8=6$，得 $h=7$。"], ["相似三角形求比", "$\\overline{FG}$ 在 $\\overline{AD}$ 上，$\\overline{AD}\\parallel\\overline{BC}$，所以 $\\triangle EFG\\sim\\triangle EBC$（AA）。<br>$E$ 到 $\\overline{FG}$ 的高是 $7-4=3$，到 $\\overline{BC}$ 的高是 7。相似三角形對應邊長比＝對應高的比：<br>$$\\overline{FG}:\\overline{BC}=3:7$$<br>答案選 (C)。"]], "tr": "誤把 $\\triangle EBG$ 的面積當成 $\\triangle EFG$ 的面積來算；$\\triangle EBG$ 包含 $E$ 往下到 $B$ 的部分，要用相減。"}, {"id": "112-23", "y": 112, "no": 23, "ch": "C12", "img": "img/hk/112_23.webp", "gimg": null, "a": 1, "rate": 0.23, "t": "矩形對角線求最短長", "c": "$AEPF$ 是矩形，對角線 $\\overline{EF}=\\overline{AP}$；$\\overline{AP}$ 最短是 $A$ 到 $\\overline{BD}$ 的垂直距離。", "st": [["把 EF 換成 AP", "$\\angle A=\\angle AEP=\\angle AFP=90^\\circ$，所以四邊形 $AEPF$ 是矩形。<br>矩形兩對角線等長，所以 $\\overline{EF}=\\overline{AP}$。問題變成：$P$ 在 $\\overline{BD}$ 上時，$\\overline{AP}$ 最短是多少？"], ["點到直線垂線最短", "$\\overline{AP}$ 最短是 $\\overline{AP}\\perp\\overline{BD}$ 時。$\\overline{BD}=\\sqrt{6^2+8^2}=10$。<br>用 $\\triangle ABD$ 面積算兩次：<br>$$\\frac{6\\times8}{2}=\\frac{10\\times\\overline{AP}}{2}\\Rightarrow\\overline{AP}=\\frac{48}{10}=\\frac{24}{5}$$<br>答案選 (B)。"]], "tr": "想直接設 $P$ 的位置算 $\\overline{EF}$，算式很複雜；看出矩形對角線相等就能轉成點到線距離。"}, {"id": "112-24", "y": 112, "no": 24, "ch": "C16", "img": "img/hk/112_24.webp", "gimg": "img/hk/112_G24.webp", "a": 3, "rate": 0.69, "t": "折線圖判讀老化速度", "c": "在圖上找每條折線穿過 14% 和 20% 兩條虛線的年份，相差最少的國家最快。", "st": [["找穿過 14% 與 20% 的年份", "「高齡社會」從 14% 開始、「超高齡社會」從 20% 開始，所以看每條線碰到 14% 和 20% 虛線的年份：<br>- 法國：約 1995 年到 14%，約 2020 年到 20%，約 25 年。<br>- 義大利：約 1988 年到 14%，約 2005 年到 20%，約 17 年。<br>- 美國：約 2014 年到 14%，約 2030 年到 20%，約 16 年。<br>- 韓國：約 2019 年到 14%，約 2025 年到 20%，約 6 年。"], ["比較", "韓國的線在 14% 到 20% 之間非常陡，只花了大約 6 年，最短。答案選 (D)。"]], "tr": "看哪條線最高就選義大利；題目問的是「花的時間」，要看線多陡，不是多高。"}, {"id": "112-25", "y": 112, "no": 25, "ch": "C16", "img": "img/hk/112_25.webp", "gimg": "img/hk/112_G24.webp", "a": 0, "rate": 0.59, "t": "高齡人口至少增加多少", "c": "2019 年恰為 14%，2025 年至少 20%；人口相同，相減得至少增加量。", "st": [["算 2019 年的高齡人口", "2019 年恰好達到高齡社會最低標準 14%：<br>$$2300\\times14\\%=322 \\text{ 萬人}$$"], ["算 2025 年至少的高齡人口", "2025 年進入超高齡社會，至少要 20%：<br>$$2300\\times20\\%=460 \\text{ 萬人}$$"], ["相減", "至少增加 $460-322=138$ 萬人。<br><b>快解</b>：總人口不變，比例至少增加 $20\\%-14\\%=6\\%$，$2300\\times6\\%=138$。答案選 (A)。"]], "tr": "只算 2019 年的 322 萬或 2025 年的 460 萬就選了；題目問的是「增加」多少。"}, {"id": "113-1", "y": 113, "no": 1, "ch": "C01", "img": "img/hk/113_1.webp", "gimg": null, "a": 0, "rate": 0.88, "t": "減去負分數", "c": "減去一個負數等於加上它的相反數，再通分相加。", "st": [["減負變加正", "減去一個負數，就等於加上它的相反數，所以<br>$$\\frac{3}{7}-\\left(-\\frac{1}{4}\\right)=\\frac{3}{7}+\\frac{1}{4}$$"], ["通分相加", "分母 7 和 4 的最小公倍數是 28，兩個分數都換成分母 28：<br>$$\\frac{3}{7}+\\frac{1}{4}=\\frac{12}{28}+\\frac{7}{28}=\\frac{19}{28}$$<br>故選 (A)。"]], "tr": "把「減負」當成「減正」算成 $\\frac{12}{28}-\\frac{7}{28}=\\frac{5}{28}$ 選 (B)；或分子分母直接相加得 $\\frac{4}{11}$。"}, {"id": "113-2", "y": 113, "no": 2, "ch": "C16", "img": "img/hk/113_2.webp", "gimg": null, "a": 0, "rate": 0.9, "t": "直三角柱展開圖", "c": "直三角柱的兩個三角形底面互相平行，每個側面都和底面垂直。", "st": [["先認出底面和側面", "直三角柱有 2 個三角形面（上、下底面）和 3 個長方形面（側面）。<br>展開圖中甲、乙都是三角形，所以甲、乙是兩個底面；丙是長方形，是一個側面。"], ["用柱體性質判斷", "- 直柱體的上、下兩個底面互相平行，所以<b>甲與乙平行</b>。<br>- 直柱體的側面都是「站直」的，和底面垂直，所以<b>甲與丙垂直</b>。<br><br>故選 (A)。"]], "tr": "看展開圖中丙和甲隔得很遠，就以為摺起來後會平行；要先分清楚哪些是底面、哪些是側面。"}, {"id": "113-3", "y": 113, "no": 3, "ch": "C04", "img": "img/hk/113_3.webp", "gimg": null, "a": 2, "rate": 0.77, "t": "代入消去法解聯立", "c": "第二式已寫成 $y=-3x$，直接代入第一式消去 $y$。", "st": [["代入消去", "因為第二式已經告訴我們 $y=-3x$，把它代進第一式，就只剩一個未知數：<br>$$5x-3(-3x)=28 \\Rightarrow 5x+9x=28 \\Rightarrow 14x=28 \\Rightarrow x=2$$"], ["求出 y 再相加", "$y=-3\\times 2=-6$，所以 $a=2$，$b=-6$，<br>$$a+b=2+(-6)=-4$$<br>故選 (C)。"]], "tr": "代入時 $-3\\times(-3x)$ 的負負得正算錯，得到 $5x-9x=28$。"}, {"id": "113-4", "y": 113, "no": 4, "ch": "C04", "img": "img/hk/113_4.webp", "gimg": null, "a": 3, "rate": 0.84, "t": "方格紙上畫坐標軸", "c": "看四點的 $x$、$y$ 坐標最大最小值，決定原點左右上下各需要幾格。", "st": [["先算需要的格數", "四點的 $x$ 坐標是 $5,-4,-3,3$：最小 $-4$、最大 $5$，所以原點<b>左邊至少 4 格、右邊至少 5 格</b>。<br><br>四點的 $y$ 坐標是 $3,-4,4,-5$：最小 $-5$、最大 $4$，所以原點<b>上面至少 4 格、下面至少 5 格</b>。"], ["逐一數格子", "沿著坐標軸數完整的格子（以原點為起點）：<br>- <b>(A) 錯誤</b>：左 4、右 5、上 5、下只有 4 格，畫不出 $(3,-5)$。<br>- <b>(B) 錯誤</b>：左 5、右只有 4 格、上 5、下 4，畫不出 $(5,3)$ 和 $(3,-5)$。<br>- <b>(C) 錯誤</b>：左 5、右只有 4 格、上 4、下 5，畫不出 $(5,3)$。<br>- <b>(D) 正確</b>：左 4、右 5、上 4、下 5，四點都畫得出來。<br><br>故選 (D)。"]], "tr": "只看原點大概在中間就選，沒有逐一數格子；或把 $x$ 坐標的需求和 $y$ 坐標的需求搞混。"}, {"id": "113-5", "y": 113, "no": 5, "ch": "C09", "img": "img/hk/113_5.webp", "gimg": null, "a": 1, "rate": 0.82, "t": "便利貼聖誕樹總張數", "c": "每層三列是公差 2 的等差數列，各層總數又成等差數列，用等差級數求和。", "st": [["找出每一層有幾張", "第 1 層第一列 1 張，每層第一列多 2 張，所以第 $k$ 層第一列是 $2k-1$ 張。<br>同一層每列多 2 張，三列分別是 $2k-1$、$2k+1$、$2k+3$，合計<br>$$(2k-1)+(2k+1)+(2k+3)=6k+3$$<br>檢查：第 1 層 $1+3+5=9$，第 2 層 $3+5+7=15$，和圖一致。"], ["10 層加起來", "各層張數 $9,15,21,\\dots$ 是首項 9、公差 6 的等差數列，第 10 層是 $6\\times10+3=63$。<br>用等差級數公式（首項加末項乘項數除以 2）：<br>$$\\frac{(9+63)\\times 10}{2}=360$$<br>故選 (B)。"]], "tr": "以為下一層第一列接著上一層最後一列往下加，或末項算成第 10 層第一列而不是整層總數。"}, {"id": "113-6", "y": 113, "no": 6, "ch": "C16", "img": "img/hk/113_6.webp", "gimg": null, "a": 3, "rate": 0.74, "t": "抽出不放回的機率", "c": "紅球抽出不放回、白球放回，先算出第 31 次抽之前箱內剩幾顆球。", "st": [["算箱內剩下的球", "白球抽到會放回，所以白球一直是 50 顆。<br>紅球抽到不放回，前 30 次抽出紅球 4 次，所以紅球剩 $10-4=6$ 顆。<br>箱內共有 $50+6=56$ 顆球。"], ["算機率", "每顆球被抽到的機會相等，抽到紅球的機率是<br>$$\\frac{6}{56}=\\frac{3}{28}$$<br>故選 (D)。"]], "tr": "忘了紅球被拿走後總球數也變少，算成 $\\frac{6}{60}$；或把白球也扣掉。"}, {"id": "113-7", "y": 113, "no": 7, "ch": "C11", "img": "img/hk/113_7.webp", "gimg": null, "a": 3, "rate": 0.71, "t": "拼貼圖案線對稱", "c": "線對稱圖形沿對稱軸對摺後兩邊完全重合；B 是 A 上下翻轉，上下排 A、B 剛好鏡射。", "st": [["看圖（五）", "圖（五）四塊都是 A，而 A 本身是「風車狀」圖案，只有轉動的對稱、沒有鏡射的對稱。<br>試著用鉛直線、水平線或對角線對摺，深色長方塊的位置都對不起來，所以圖（五）<b>不是</b>線對稱圖形。"], ["看圖（六）", "圖（六）上排是兩個 A，下排是兩個 B。因為 B 就是 A 上下翻轉，<br>以大正方形中間的<b>水平線</b>為對稱軸對摺，上排的 A 剛好翻成下排的 B，兩邊完全重合，所以圖（六）<b>是</b>線對稱圖形。<br><br>故選 (D)。"]], "tr": "以為四塊一樣的圖拼起來比較「整齊」就一定對稱；其實相同圖案平移排列不會產生鏡射對稱。"}, {"id": "113-8", "y": 113, "no": 8, "ch": "C01", "img": "img/hk/113_8.webp", "gimg": null, "a": 2, "rate": 0.68, "t": "科學記號比大小", "c": "先比 10 的次方，次方大的數大；次方一樣再比前面的數。", "st": [["先比指數", "$a$、$b$ 都是 $10^{-5}$，$c$ 是 $10^{-6}$。因為 $10^{-6}$ 只有 $10^{-5}$ 的十分之一，<br>$$c=6.3\\times10^{-6}=0.63\\times10^{-5}$$<br>所以 $c$ 最小。"], ["指數相同比前面", "$a$ 和 $b$ 都是 $10^{-5}$，比前面的數：$3.2\\lt 7.5$，所以 $a\\lt b$。<br><br>因此 $c\\lt a\\lt b$，故選 (C)。"]], "tr": "以為 $-6$ 的「6」比較大，所以 $10^{-6}$ 比較大；負指數越小（越負）數值越小。"}, {"id": "113-9", "y": 113, "no": 9, "ch": "C16", "img": "img/hk/113_9.webp", "gimg": null, "a": 2, "rate": 0.78, "t": "判讀癌症存活率長條圖", "c": "讀長條圖的高度，算出每種癌症三期與四期的差距再比較。", "st": [["判斷甲", "乳癌是斜線長條，一到四期大約是 $99\\%$、$97\\%$、$88\\%$、$53\\%$。<br>最低的四期也略高於 $50\\%$，所以甲<b>正確</b>。"], ["判斷乙", "從圖讀出三期、四期的存活率，算差距：<br>- 胃癌：約 $56-13=43$<br>- 肝癌：約 $22-15=7$<br>- 大腸癌：約 $83-29=54$<br>- 乳癌：約 $88-53=35$<br><br>相差最多的是<b>大腸癌</b>，不是胃癌，所以乙<b>錯誤</b>。故選 (C)。"]], "tr": "看到胃癌四期最低就以為差距最大；差距要「三期減四期」，大腸癌三期很高所以差最多。"}, {"id": "113-10", "y": 113, "no": 10, "ch": "C06", "img": "img/hk/113_10.webp", "gimg": null, "a": 2, "rate": 0.65, "t": "提公因式分解", "c": "兩項都有 $(5x-2)$，把它提出來後整理剩下的式子。", "st": [["找共同的因式", "第一項 $5x(5x-2)$ 和第二項 $4(5x-2)^2$ 都有 $(5x-2)$，把它提出來：<br>$$5x(5x-2)-4(5x-2)^2=(5x-2)\\left[5x-4(5x-2)\\right]$$"], ["化簡中括號", "$$5x-4(5x-2)=5x-20x+8=-15x+8$$<br>所以原式 $=(5x-2)(-15x+8)$，故選 (C)。"]], "tr": "$-4\\times(-2)$ 忘了變號寫成 $-8$，或提出後忘了乘 4，得到 $5x-(5x-2)$。"}, {"id": "113-11", "y": 113, "no": 11, "ch": "C07", "img": "img/hk/113_11.webp", "gimg": null, "a": 0, "rate": 0.62, "t": "分母有理化", "c": "分子分母同乘 $4+\\sqrt{7}$，用平方差公式消去分母的根號。", "st": [["分母有理化", "分母有根號不好看，分子分母同乘 $4+\\sqrt{7}$，分母就能用平方差公式 $(a-b)(a+b)=a^2-b^2$ 消掉根號：<br>$$\\frac{9}{4-\\sqrt{7}}=\\frac{9(4+\\sqrt{7})}{(4-\\sqrt{7})(4+\\sqrt{7})}=\\frac{9(4+\\sqrt{7})}{16-7}=\\frac{9(4+\\sqrt{7})}{9}=4+\\sqrt{7}$$"], ["對照求 a+b", "$4+\\sqrt{7}=a+b\\sqrt{7}$，所以 $a=4$，$b=1$，$a+b=5$。故選 (A)。"]], "tr": "乘 $4-\\sqrt{7}$ 而不是 $4+\\sqrt{7}$；或把 $\\sqrt{7}$ 的係數 1 忘掉，以為 $b=0$。"}, {"id": "113-12", "y": 113, "no": 12, "ch": "C10", "img": "img/hk/113_12.webp", "gimg": null, "a": 2, "rate": 0.7, "t": "二次函數最大最小值", "c": "$y=a(x-h)^2+k$：$a\\gt 0$ 開口向上有最小值、$a\\lt 0$ 開口向下有最大值，都發生在 $x=h$。", "st": [["看甲", "甲：$y=(x+20)^2+60=(x-(-20))^2+60$，平方項係數是 1（正），開口向上，有<b>最小值</b>，發生在 $x=-20$，不是 $x=20$。所以 (A)、(B) 都錯。"], ["看乙", "乙：$y=-(x-30)^2+60$，平方項係數是 $-1$（負），開口向下，有<b>最大值</b> 60，發生在 $x=30$。<br>- <b>(C) 正確</b>。<br>- <b>(D) 錯誤</b>：乙沒有最小值。<br><br>故選 (C)。"]], "tr": "看到 $(x+20)^2$ 就以為頂點在 $x=20$；括號裡是「加 20」，頂點是 $x=-20$。"}, {"id": "113-13", "y": 113, "no": 13, "ch": "C05", "img": "img/hk/113_13.webp", "gimg": null, "a": 1, "rate": 0.66, "t": "螢幕解析度比例", "c": "比例不變就不會有黑邊，把各選項化成最簡整數比和 $16:9$ 比較。", "st": [["化簡原本的比", "$1920:1080$，兩數同除以 120，得到<br>$$1920:1080=16:9$$"], ["逐一化簡選項", "- <b>(A)</b> $1680:1050=8:5$，不是 $16:9$。<br>- <b>(B)</b> $1600:900=16:9$，比例相同。<br>- <b>(C)</b> $1440:900=8:5$，不是 $16:9$。<br>- <b>(D)</b> $1280:1024=5:4$，不是 $16:9$。<br><br>故選 (B)。"]], "tr": "只看寬度或高度其中一個數字接近就選；要整個比化到最簡才能比較。"}, {"id": "113-14", "y": 113, "no": 14, "ch": "C03", "img": "img/hk/113_14.webp", "gimg": null, "a": 2, "rate": 0.55, "t": "改搭公車減碳天數", "c": "每天少排的碳量 × 天數 &gt; 800，解一元一次不等式後取最小整數。", "st": [["算每天少排多少", "每移動 1 公里，汽車比公車多排 $0.17-0.04=0.13$ 公斤。<br>每天來回 20 公里，所以每天少排 $20\\times0.13=2.6$ 公斤。"], ["列不等式", "設改搭 $x$ 天，減少的量要<b>超過</b> 800 公斤：<br>$$2.6x\\gt 800 \\Rightarrow x\\gt \\frac{800}{2.6}=307.69\\cdots$$<br>$x$ 是天數，要取整數，最少是 308 天。故選 (C)。"]], "tr": "直接拿 $20\\times0.04$ 或 $20\\times0.17$ 去除，沒有算「差」；或 $307.69$ 四捨五入成 307 天，307 天其實還不夠。"}, {"id": "113-15", "y": 113, "no": 15, "ch": "C02", "img": "img/hk/113_15.webp", "gimg": null, "a": 1, "rate": 0.55, "t": "最簡分數通分", "c": "由通分後的分子推出擴分倍數，得到 $5a=3b$，再配合「最簡分數」判斷 $a$ 的因數。", "st": [["找出擴分的倍數", "甲的分子從 10 變 50，是分子分母同乘 5，新分母是 $5a$。<br>乙的分子從 18 變 54，是分子分母同乘 3，新分母是 $3b$。<br>通分後分母相同，所以<br>$$5a=3b$$"], ["判斷 a 的倍數", "- $5a=3b$ 是 3 的倍數，而 5 和 3 互質，所以 $a$ <b>是 3 的倍數</b>。<br>- $\\frac{10}{a}$ 是最簡分數，代表 $a$ 和 10 沒有公因數（除了 1），所以 $a$ <b>不是 5 的倍數</b>（也不是 2 的倍數）。<br><br>例如 $a=3$、$b=5$：$\\frac{10}{3}=\\frac{50}{15}$、$\\frac{18}{5}=\\frac{54}{15}$，符合題意。故選 (B)。"]], "tr": "沒用到「最簡分數」這個條件，看到 $5a$ 就以為 $a$ 是 5 的倍數。"}, {"id": "113-16", "y": 113, "no": 16, "ch": "C10", "img": "img/hk/113_16.webp", "gimg": null, "a": 1, "rate": 0.52, "t": "氣溫上升的線性函數", "c": "每十年上升 $0.08$ 度，每年上升 $0.008$ 度，從 2020 年的 $14.88$ 度開始加。", "st": [["換算每年上升幾度", "每十年上升 $0.08$ 度（°C），每年上升相同度數，所以每年上升<br>$$0.08\\div10=0.008$$<br>也就是每年上升 $0.008$ 度。"], ["寫出式子", "起點是 2020 年的 $14.88$°C，之後第 $x$ 年共上升 $0.008x$ 度，所以氣溫是<br>$$14.88+0.008x$$<br>1880 年只是資料的起始年，跟「從 2020 年往後算」無關，所以不用加 $2020-1880$。故選 (B)。"]], "tr": "忘了把「每十年」換成「每年」選 (A)；或把 1880～2020 這段年數也加進去選 (D)。"}, {"id": "113-17", "y": 113, "no": 17, "ch": "C14", "img": "img/hk/113_17.webp", "gimg": null, "a": 0, "rate": 0.5, "t": "點與圓的位置關係", "c": "點到圓心距離和半徑比大小；三角形中大角對大邊。", "st": [["求出角 A 並比邊", "$\\angle A=180^\\circ-55^\\circ-65^\\circ=60^\\circ$。<br>三角形中大角對大邊：<br>- $\\overline{AB}$ 對 $\\angle C=65^\\circ$<br>- $\\overline{BC}$ 對 $\\angle A=60^\\circ$<br>- $\\overline{AC}$ 對 $\\angle B=55^\\circ$<br><br>所以 $\\overline{AC}\\lt \\overline{BC}\\lt \\overline{AB}$。"], ["判斷 A 的位置", "兩圓半徑都是 $\\overline{BC}$。<br>- 圓 $B$：$A$ 到圓心 $B$ 的距離 $\\overline{AB}\\gt \\overline{BC}$，所以 $A$ 在圓 $B$ <b>外部</b>。<br>- 圓 $C$：$A$ 到圓心 $C$ 的距離 $\\overline{AC}\\lt \\overline{BC}$，所以 $A$ 在圓 $C$ <b>內部</b>。<br><br>故選 (A)。"]], "tr": "把「對邊」看錯，例如以為 $\\overline{AB}$ 對的是 $\\angle B$。"}, {"id": "113-18", "y": 113, "no": 18, "ch": "C12", "img": "img/hk/113_18.webp", "gimg": null, "a": 0, "rate": 0.43, "t": "全等平行四邊形周長", "c": "由全等對應邊求邊長，再用平行四邊形對角相等找出等腰三角形 $EFC$。", "st": [["用對應邊求長度", "$A\\to H$、$B\\to E$、$C\\to F$、$D\\to G$，對應邊相等：<br>$$\\overline{HE}=\\overline{AB}=7,\\ \\overline{EF}=\\overline{BC}=5,\\ \\overline{FG}=\\overline{CD}=7,\\ \\overline{GH}=\\overline{DA}=5$$<br>又 $\\overline{CG}=\\overline{FG}-\\overline{FC}=7-3=4$。"], ["找出 EC 的長", "還缺 $\\overline{EC}$。因為 $\\angle EFG$ 對應 $\\angle BCD$，所以 $\\angle EFC=\\angle BCD=\\angle ECF$。<br>$\\triangle EFC$ 兩底角相等，是等腰三角形，所以<br>$$\\overline{EC}=\\overline{EF}=5$$"], ["算周長", "四邊形 $ECGH$ 的周長：<br>$$\\overline{EC}+\\overline{CG}+\\overline{GH}+\\overline{HE}=5+4+5+7=21$$<br>故選 (A)。"]], "tr": "對應頂點沒對好，把 $\\overline{EH}$ 當成 5；或找不到 $\\overline{EC}$，沒想到用對應角證出等腰三角形。"}, {"id": "113-19", "y": 113, "no": 19, "ch": "C01", "img": "img/hk/113_19.webp", "gimg": null, "a": 1, "rate": 0.52, "t": "倒數在數線上的位置", "c": "$p\\lt -2$ 時，倒數 $q=\\frac{1}{p}$ 介於 $-\\frac{1}{2}$ 和 0 之間。", "st": [["判斷 q 的範圍", "$P$ 在 $A$ 左側，所以 $p\\lt -2$，$p$ 是負數。負數的倒數也是負數，且 $p$ 離 0 越遠，倒數就越靠近 0。<br>例如 $p=-4$ 時 $q=-\\frac{1}{4}$；一般而言<br>$$-\\frac{1}{2}\\lt q\\lt 0$$"], ["比較距離", "$q$ 在 $-\\frac{1}{2}$ 和 0 之間，所以 $Q$ 在 $\\overline{AO}$ 上。<br>$\\overline{QO}=|q|\\lt \\frac{1}{2}$，而 $\\overline{AQ}=2-|q|\\gt \\frac{3}{2}$，所以 $\\overline{AQ}\\gt \\overline{QO}$。故選 (B)。"]], "tr": "以為倒數會變號而跑到右邊 $\\overline{OB}$ 上；倒數不會改變正負號。"}, {"id": "113-20", "y": 113, "no": 20, "ch": "C11", "img": "img/hk/113_20.webp", "gimg": null, "a": 3, "rate": 0.54, "t": "四邊形內角和比角", "c": "四邊形內角和 $360^\\circ$，分別在 $ABEG$、$GFCD$ 中把 $\\angle 3$、$\\angle 4$ 用 $\\angle 1$、$\\angle 2$ 表示。", "st": [["看四邊形 ABEG", "$\\angle BEG$ 和 $\\angle 1$ 互補，$\\angle BEG=180^\\circ-\\angle1$。四邊形內角和 $360^\\circ$：<br>$$100^\\circ+85^\\circ+(180^\\circ-\\angle1)+\\angle3=360^\\circ \\Rightarrow \\angle3=\\angle1-5^\\circ$$"], ["看四邊形 GFCD", "$\\angle GFC=180^\\circ-\\angle2$：<br>$$105^\\circ+70^\\circ+(180^\\circ-\\angle2)+\\angle4=360^\\circ \\Rightarrow \\angle4=\\angle2+5^\\circ$$"], ["比較選項", "- $\\angle3+\\angle4=(\\angle1-5^\\circ)+(\\angle2+5^\\circ)=\\angle1+\\angle2$，所以 (A)、(B) 都錯。<br>- $\\angle1+\\angle4=\\angle1+\\angle2+5^\\circ$，而 $\\angle2+\\angle3=\\angle1+\\angle2-5^\\circ$，所以 $\\angle1+\\angle4\\gt \\angle2+\\angle3$。<br><br>故選 (D)。"]], "tr": "把 $\\angle1$ 直接當成四邊形 $ABEG$ 的內角，忘了它在 $E$ 點是外側的角，要用 $180^\\circ$ 去減。"}, {"id": "113-21", "y": 113, "no": 21, "ch": "C14", "img": "img/hk/113_21.webp", "gimg": null, "a": 3, "rate": 0.38, "t": "兩半圓交點的弧度", "c": "$B$ 是半圓 $AC$ 的圓心，$\\overset{\\frown}{CE}=58^\\circ$ 得 $\\angle EBC=58^\\circ$，再在半圓 $BD$ 的圓中用等腰三角形求圓心角。", "st": [["用圓心角讀出角度", "$B$ 是 $\\overline{AC}$ 的中點，也就是半圓 $AC$ 的圓心。弧的度數等於所對的圓心角，所以<br>$$\\angle EBC=\\overset{\\frown}{CE}=58^\\circ$$"], ["在半圓 BD 中找圓心角", "設 $M$ 為 $\\overline{BD}$ 的中點，即半圓 $BD$ 的圓心，連 $\\overline{ME}$。<br>$\\overline{MB}=\\overline{ME}$（都是半徑），$\\triangle MBE$ 是等腰三角形，$\\angle MEB=\\angle MBE=58^\\circ$，<br>$$\\angle BME=180^\\circ-58^\\circ-58^\\circ=64^\\circ$$"], ["得到弧度", "$\\overset{\\frown}{BE}$ 的度數等於它的圓心角 $\\angle BME$，所以 $\\overset{\\frown}{BE}=64^\\circ$。故選 (D)。"]], "tr": "誤以為 $C$ 是半圓 $BD$ 的圓心；圓心是 $\\overline{BD}$ 的中點，不是 $C$。也有人以為兩段弧在同一個圓上直接寫 58。"}, {"id": "113-22", "y": 113, "no": 22, "ch": "C15", "img": "img/hk/113_22.webp", "gimg": null, "a": 0, "rate": 0.34, "t": "重心三等分面積", "c": "重心把三角形分成三塊等面積；兩點到 $\\overline{BC}$ 的距離相同且在同側，連線就和 $\\overline{BC}$ 平行。", "st": [["重心的面積性質", "$\\triangle ABC$ 面積 $=5+4+3=12$。<br>重心 $G$ 和三頂點連線，分出的三塊面積相等，所以<br>$$\\triangle GBC=\\triangle GCA=\\triangle GAB=12\\div3=4$$"], ["和 D 比較", "- $\\triangle GBC=4=\\triangle DBC$，面積相同。兩個三角形底邊都是 $\\overline{BC}$，所以 $G$、$D$ 到 $\\overline{BC}$ 的高相等，且都在 $\\triangle ABC$ 內部（同一側），因此 $\\overline{DG}\\parallel\\overline{BC}$。<br>- $\\triangle GCA=4$，但 $\\triangle DCA=3$，面積不同，(C)、(D) 錯。<br><br>故選 (A)。"]], "tr": "知道面積相同卻不敢判斷平行；同底等高、又在同側的兩點，連線一定平行於底。"}, {"id": "113-23", "y": 113, "no": 23, "ch": "C12", "img": "img/hk/113_23.webp", "gimg": null, "a": 1, "rate": 0.3, "t": "等腰梯形摺紙比例", "c": "$ABED$ 是平行四邊形、$\\triangle DEC$ 等腰；摺過去後 $\\triangle BEC'$ 也是等腰，邊長一路傳遞。", "st": [["整理已知的邊與角", "$\\overline{AD}\\parallel\\overline{BE}$ 且 $\\overline{DE}\\parallel\\overline{AB}$，所以 $ABED$ 是平行四邊形，$\\overline{AB}=\\overline{DE}=4$，也得 $\\overline{DC}=\\overline{AB}=4=\\overline{DE}$。<br>$\\triangle DEC$ 中 $\\overline{DE}=\\overline{DC}$，所以 $\\angle DEC=\\angle C=\\angle B$。為了方便，把這個角記作 $\\angle B$。"], ["摺過去後的三角形", "把摺過去後落在 $\\overline{AB}$ 上的點記作 $C'$（圖（十六）中的 $C$）。摺紙前後全等，所以 $\\overline{EC'}=\\overline{EC}=2$，$\\angle DEC'=\\angle DEC=\\angle B$。<br>$\\angle BEC'=180^\\circ-\\angle DEC-\\angle DEC'=180^\\circ-2\\angle B$，<br>在 $\\triangle BEC'$ 中，$\\angle BC'E=180^\\circ-\\angle B-(180^\\circ-2\\angle B)=\\angle B$。<br>兩底角相等，所以 $\\overline{BE}=\\overline{EC'}=2$。"], ["求 BC' 的長", "$\\triangle DEC$ 和 $\\triangle EBC'$ 三個角都對應相等（都是 $\\angle B$、$\\angle B$ 和頂角），兩者相似：<br>$$\\frac{\\overline{BC'}}{\\overline{EC}}=\\frac{\\overline{EB}}{\\overline{DE}} \\Rightarrow \\frac{\\overline{BC'}}{2}=\\frac{2}{4} \\Rightarrow \\overline{BC'}=1$$<br>所以 $\\overline{AC'}=4-1=3$，$\\overline{BC'}:\\overline{AC'}=1:3$。故選 (B)。"]], "tr": "沒發現 $\\triangle BEC'$ 是等腰三角形，或以為 $C'$ 是 $\\overline{AB}$ 的中點而選 (A)。"}, {"id": "113-24", "y": 113, "no": 24, "ch": "C08", "img": "img/hk/113_24.webp", "gimg": "img/hk/113_G24.webp", "a": 3, "rate": 0.35, "t": "理想體重算法相同嗎", "c": "設身高 $h$，兩種算法相等列方程式，看有沒有解；二次方程式用配方看是否可能等於 0。", "st": [["判斷甲（算法①＝算法②）", "設身高 $h$ 公尺。女性：算法① $=22h^2$，算法② $=(100h-70)\\times0.6=60h-42$。<br>若相同，$22h^2=60h-42$，即 $22h^2-60h+42=0$。配方看看：<br>$$22h^2-60h+42=22\\left(h-\\frac{15}{11}\\right)^2+\\frac{12}{11}$$<br>平方一定 $\\ge0$，所以左式一定 $\\ge\\frac{12}{11}\\gt 0$，不可能等於 0。甲<b>錯誤</b>。"], ["判斷乙（算法②＝算法③）", "算法③ $=(100h-158)\\times0.5+52=50h-27$。<br>若相同，$60h-42=50h-27 \\Rightarrow 10h=15 \\Rightarrow h=1.5$。<br>身高 $1.5$ 公尺的女性兩種算法都是 48 公斤，所以乙<b>正確</b>。故選 (D)。"]], "tr": "把算法③展開時 $-158\\times0.5=-79$ 算錯；或沒算就憑感覺說「總有人會相同」。"}, {"id": "113-25", "y": 113, "no": 25, "ch": "C03", "img": "img/hk/113_25.webp", "gimg": "img/hk/113_G24.webp", "a": 1, "rate": 0.33, "t": "換算法重新歸類體重", "c": "先求兩種算法的理想體重，再把「正常」的體重範圍換成新理想體重的百分比。", "st": [["求出正常體重範圍", "身高 $1.8$ 公尺的男性，算法②：$(180-80)\\times0.7=70$ 公斤。<br>被歸類為正常，所以實際體重 $W$ 滿足<br>$$70\\times90\\%\\le W\\le70\\times110\\% \\Rightarrow 63\\le W\\le77$$"], ["改用算法③", "算法③：$(180-170)\\times0.6+62=68$ 公斤。把 $W$ 的範圍換成 68 的百分比：<br>$$\\frac{63}{68}\\approx92.6\\%,\\quad \\frac{77}{68}\\approx113.2\\%$$<br>所以 $W$ 介於理想體重的約 $92.6\\%$ 到 $113.2\\%$。"], ["對照表（二）", "$92.6\\%\\sim110\\%$ 落在「正常」，$110\\%\\sim113.2\\%$ 落在「過重」，不會低到 $90\\%$ 以下，所以不會「過輕」。<br>可能的類別是正常、過重，故選 (B)。"]], "tr": "拿男性的算法套成女性的係數；或只算 70 和 68 差不多就以為一定還是正常。"}, {"id": "114-1", "y": 114, "no": 1, "ch": "C01", "img": "img/hk/114_1.webp", "gimg": null, "a": 2, "rate": 0.75, "t": "同底數指數的乘除", "c": "底數相同時，相乘指數相加、相除指數相減。", "st": [["看出底數都一樣", "三個數的底數都是 7，所以可以直接用指數律，不必真的算出 $7^{10}$ 有多大。<br><br>- 相乘：$a^m\\times a^n=a^{m+n}$<br>- 相除：$a^m\\div a^n=a^{m-n}$"], ["由左到右計算", "$$7^{10}\\times 7^{2}\\div 7^{4}=7^{10+2-4}=7^{8}$$<br><br>所以答案是 (C)。"]], "tr": "把相乘看成指數相乘（$7^{20}$），或把相除看成指數相除。"}, {"id": "114-2", "y": 114, "no": 2, "ch": "C06", "img": "img/hk/114_2.webp", "gimg": null, "a": 1, "rate": 0.82, "t": "多項式減法去括號", "c": "減號後面的括號拿掉時，括號裡每一項都要變號。", "st": [["先去括號", "第二個括號前面是減號，拿掉括號時，裡面的 $4$ 和 $-3x$ <b>都要變號</b>：<br>$$(5x^2-2x)-(4-3x)=5x^2-2x-4+3x$$"], ["合併同類項", "$x$ 的項：$-2x+3x=x$，常數項只有 $-4$：<br>$$5x^2+x-4$$<br><br>所以答案是 (B)。"]], "tr": "只把 4 變號、忘了 $-3x$ 也要變成 $+3x$，就會誤選 (D)。"}, {"id": "114-3", "y": 114, "no": 3, "ch": "C11", "img": "img/hk/114_3.webp", "gimg": null, "a": 2, "rate": 0.88, "t": "擦去線段後的線對稱", "c": "線對稱圖形沿對稱軸對摺後兩邊完全重合；擦掉的兩段必須互相對稱（或都在軸上），剩下的圖才仍線對稱。", "st": [["找出原圖的對稱軸", "原圖以「左上正方形右下角那個點」為中心，沿著<b>左上到右下的斜線</b>對摺會重合：<br>① 和 ② 互相對應，③ 和 ④ 互相對應。"], ["逐一檢查", "- <b>(A) 擦去①和②</b>：這兩段剛好是一對對應線段，同時擦掉，斜線仍是對稱軸，<b>仍線對稱</b>。<br>- <b>(B) 擦去①和③</b>：剩下 ② 在左、④ 在右，以中間那條<b>鉛垂線</b>為軸，左半邊和右半邊一模一樣，<b>仍線對稱</b>。<br>- <b>(C) 擦去②和③</b>：剩下 ① 在左上方，但右上方沒有對應線段；斜線軸也不行（① 的對應段 ② 被擦了），找不到任何對稱軸，<b>不是線對稱</b>。<br>- <b>(D) 擦去②和④</b>：剩下 ① 在上、③ 在下，以中間那條<b>水平線</b>為軸，上下一模一樣，<b>仍線對稱</b>。<br><br>所以答案是 (C)。"]], "tr": "只想到原本那條斜的對稱軸，沒發現擦掉後可能出現新的鉛垂或水平對稱軸。"}, {"id": "114-4", "y": 114, "no": 4, "ch": "C04", "img": "img/hk/114_4.webp", "gimg": null, "a": 1, "rate": 0.77, "t": "加減消去法解聯立", "c": "兩式的 $y$ 係數一正一負，直接相加就能消去 $y$。", "st": [["兩式相加消去 y", "因為一式是 $+2y$、另一式是 $-2y$，相加剛好抵消：<br>$$(37x+2y)+(23x-2y)=81+39\\Rightarrow 60x=120\\Rightarrow x=2$$"], ["代回求 2y", "題目要的是 $a+2b$，所以只要求出 $2y$ 就好，不必算出 $y$：<br>$$37\\times2+2y=81\\Rightarrow 2y=7$$<br><br>$$a+2b=2+7=9$$，答案是 (B)。"]], "tr": "求出 $b=\\frac{7}{2}$ 後忘記乘 2，算成 $2+\\frac{7}{2}$。"}, {"id": "114-5", "y": 114, "no": 5, "ch": "C11", "img": "img/hk/114_5.webp", "gimg": null, "a": 2, "rate": 0.82, "t": "三角形內角和與外角", "c": "用三角形內角和 $180^\\circ$，以及外角等於兩個不相鄰內角的和。", "st": [["在大三角形 ABC 中求 p+q", "$\\angle BAC=p^\\circ+30^\\circ$，三個內角加起來是 $180^\\circ$：<br>$$(p+30)+q+70=180\\Rightarrow p+q=80$$"], ["在三角形 ADC 中求 r", "$r^\\circ$ 是 $\\angle ADC$，在 $\\triangle ADC$ 裡：<br>$$r=180-30-70=80$$<br><br>（也可以想成 $r^\\circ$ 是 $\\triangle ABD$ 的外角，等於 $p+q$。）"], ["相加", "$$p+q+r=80+80=160$$，答案是 (C)。"]], "tr": "誤以為 $p+q+r$ 是某個三角形的內角和而直接選 180。"}, {"id": "114-6", "y": 114, "no": 6, "ch": "C04", "img": "img/hk/114_6.webp", "gimg": null, "a": 0, "rate": 0.77, "t": "坐標平面上的移動", "c": "向下移動 $y$ 坐標變小，向右移動 $x$ 坐標變大。", "st": [["判斷坐標怎麼變", "從 $(-1,2)$ 出發：<br><br>- 向下移動：$y$ 坐標變小，所以終點的 $y\\lt 2$。<br>- 向右移動：$x$ 坐標變大，所以終點的 $x\\gt -1$。"], ["對照選項", "要同時滿足 $x\\gt -1$、$y\\lt 2$：<br><br>- (A) $(4,1)$：$4\\gt -1$、$1\\lt 2$，符合。<br>- (B) $(4,3)$：$3\\gt 2$，不符。<br>- (C)(D) $x=-4\\lt -1$，不符。<br><br>答案是 (A)。"]], "tr": "把「向下」想成 $x$ 變小，左右和上下對應的坐標弄反。"}, {"id": "114-7", "y": 114, "no": 7, "ch": "C16", "img": "img/hk/114_7.webp", "gimg": null, "a": 0, "rate": 0.78, "t": "直方圖讀人口變動", "c": "60 歲以上包含 60～70、70～80、80 歲以上三組，把三組的變動數（含正負）相加。", "st": [["找出 60 歲以上的組", "年齡軸 60 以後有三根長條：<br><br>- 60～70 歲：$-109$ 萬<br>- 70～80 歲：$112$ 萬<br>- 80 歲以上：$204$ 萬"], ["把正負數相加", "$$-109+112+204=207$$<br><br>結果是正數，代表<b>增加</b> 207 萬人，答案是 (A)。"]], "tr": "漏掉 60～70 歲那組（$-109$），算成增加 316 萬；或只看 70 歲以上。"}, {"id": "114-8", "y": 114, "no": 8, "ch": "C07", "img": "img/hk/114_8.webp", "gimg": null, "a": 2, "rate": 0.75, "t": "根式的分配律", "c": "$\\sqrt{a}\\times\\sqrt{b}=\\sqrt{ab}$，乘開後再化成最簡根式。", "st": [["用分配律乘開", "$$(2\\sqrt3+\\sqrt6)\\times\\sqrt2=2\\sqrt6+\\sqrt{12}$$"], ["化簡根式", "$\\sqrt{12}=\\sqrt{4\\times3}=2\\sqrt3$，所以結果是<br>$$2\\sqrt3+2\\sqrt6$$<br><br>答案是 (C)。"]], "tr": "$\\sqrt{12}$ 沒化簡就找不到選項，或誤把 $2\\sqrt3\\times\\sqrt2$ 算成 $2\\sqrt5$。"}, {"id": "114-9", "y": 114, "no": 9, "ch": "C09", "img": "img/hk/114_9.webp", "gimg": null, "a": 0, "rate": 0.72, "t": "停車位與下車區總寬", "c": "20 個停車位排一列，「相鄰兩位之間」只有 19 個空隙，所以下車區有 19 個。", "st": [["數下車區有幾個", "從圖可看出，下車區只出現在<b>兩個停車位之間</b>，最左和最右沒有。<br>20 個停車位之間共有 $20-1=19$ 個空隙，所以有 19 個下車區。"], ["計算總寬度", "$$20\\times200+19\\times150=4000+2850=6850$$<br><br>總寬度是 6850 公分。<br><br>答案是 (A)。"]], "tr": "以為下車區也是 20 個，算成 7000；這就是「種樹問題」的間隔數比棵數少 1。"}, {"id": "114-10", "y": 114, "no": 10, "ch": "C06", "img": "img/hk/114_10.webp", "gimg": null, "a": 0, "rate": 0.58, "t": "平方差公式比大小", "c": "$a^2-b^2=(a+b)(a-b)$，把每個選項拆成四個數相乘再比較。", "st": [["每個括號用平方差公式拆開", "- (A) $(106^2-4^2)(108^2-2^2)=(110\\times102)\\times(110\\times106)$<br>- (B) $(107^2-3^2)(107^2-1^2)=(110\\times104)\\times(108\\times106)$<br>- (C) $(108^2-2^2)(106^2-2^2)=(110\\times106)\\times(108\\times104)$<br>- (D) $(109^2-1^2)(105^2-1^2)=(110\\times108)\\times(106\\times104)$"], ["比較四個因數", "(B)(C)(D) 都是 $104\\times106\\times108\\times110$，值相同；<br>(A) 是 $102\\times106\\times110\\times110$，跟其他不一樣。<br><br>答案是 (A)。"]], "tr": "想直接硬算平方，算到一半出錯；平方差公式拆開後只要比對因數就好。"}, {"id": "114-11", "y": 114, "no": 11, "ch": "C16", "img": "img/hk/114_11.webp", "gimg": null, "a": 1, "rate": 0.72, "t": "翻牌比大小的機率", "c": "先找出兩人蓋住的牌，共 $3\\times3=9$ 種等可能結果，數出阿嘉較大的情形。", "st": [["找出蓋住的牌", "阿嘉翻開 1、3，蓋住的是 <b>2、4、5</b>；<br>小楊翻開 5、2，蓋住的是 <b>1、3、4</b>。<br>兩人各翻一張，共 $3\\times3=9$ 種結果，機會都相等。"], ["數阿嘉比較大的情形", "- 阿嘉翻到 2：只大於 1，1 種<br>- 阿嘉翻到 4：大於 1、3，2 種<br>- 阿嘉翻到 5：大於 1、3、4，3 種<br><br>共 $1+2+3=6$ 種，機率 $\\frac{6}{9}=\\frac{2}{3}$，答案是 (B)。"]], "tr": "拿已經翻開的牌來比，或把 4 對 4 平手也算成阿嘉大。"}, {"id": "114-12", "y": 114, "no": 12, "ch": "C16", "img": "img/hk/114_12.webp", "gimg": null, "a": 3, "rate": 0.66, "t": "木片能否組成正三角錐", "c": "正三角錐的三條側稜要一樣長，所以每個側面必須是「底邊 3、另兩邊相等」的等腰三角形。", "st": [["想清楚正三角錐的條件", "底面是邊長 3 的正三角形（甲），所以每個側面都要有一邊是 3 貼著底面。<br>相鄰兩個側面會共用一條側稜，三條側稜要能兩兩對上；正三角錐的三條側稜等長，側面要是<b>等腰三角形</b>。"], ["檢查阿林的乙", "乙的三邊是 3、3、2。拿一邊 3 貼底面後，往上的兩邊是 3 和 2，<b>不一樣長</b>。<br>三片乙繞一圈時，每條側稜要被兩片共用：第一片給 3 和 2，第二片要接 2 就得給 3，第三片接 3 又給 2，最後回到第一片時 2 對不上 3，<b>合不起來</b>。"], ["檢查小博的丙", "丙的三邊是 4、4、3。3 貼底面，往上兩邊都是 4，是等腰三角形，三片側稜都是 4，可以合成正三角錐（4 比底面三角形中心到頂點的距離長，立得起來）。<br><br>所以阿林不能、小博能，答案是 (D)。"]], "tr": "看到乙也有兩邊 3 就以為能拼；要注意 3 那邊要拿去貼底面，剩下的兩邊才是側稜。"}, {"id": "114-13", "y": 114, "no": 13, "ch": "C08", "img": "img/hk/114_13.webp", "gimg": null, "a": 0, "rate": 0.61, "t": "平方式的解的情形", "c": "$(x-h)^2=k$：$k\\gt 0$ 兩相異解，$k=0$ 兩相同解，$k\\lt 0$ 無解。", "st": [["看甲方程式", "$(x-4)^2=9$，右邊 9 大於 0，開平方：<br>$$x-4=\\pm3\\Rightarrow x=7,\\ x=1$$<br>有<b>兩個相異的解</b>。"], ["看乙方程式", "$(x+9)^2=-4$，任何數的平方都不會是負數，所以<b>無解</b>。<br><br>答案是 (A)。"]], "tr": "開平方時只取正的，以為甲只有一個解；或把乙算成 $x+9=\\pm2$。"}, {"id": "114-14", "y": 114, "no": 14, "ch": "C03", "img": "img/hk/114_14.webp", "gimg": null, "a": 2, "rate": 0.56, "t": "早餐組合的收入", "c": "設早餐組合賣出 $x$ 組，單點咖啡與三明治的數量都用 $x$ 表示，列一元一次方程式。", "st": [["設未知數", "設賣出早餐組合 $x$ 組，每組用掉 1 杯咖啡和 1 個三明治，所以：<br><br>- 單點咖啡：$120-x$ 杯<br>- 單點三明治：$100-x$ 個"], ["列方程式並求解", "$$70x+50(120-x)+40(100-x)=8700$$<br>$$70x+6000-50x+4000-40x=8700$$<br>$$10000-20x=8700\\Rightarrow x=65$$"], ["算早餐組合收入", "$$70\\times65=4550$$<br>早餐組合收入是 4550 元，在 4500～4599 元之間，答案是 (C)。<br><br><b>快解</b>：若全部單點，收入是 $120\\times50+100\\times40=10000$ 元；每賣一組早餐組合就少收 $50+40-70=20$ 元，少了 $1300$ 元，所以有 $1300\\div20=65$ 組。"]], "tr": "求出 65 組就停了，忘記題目要的是「收入」$70\\times65$。"}, {"id": "114-15", "y": 114, "no": 15, "ch": "C01", "img": "img/hk/114_15.webp", "gimg": null, "a": 1, "rate": 0.6, "t": "絕對值找原點位置", "c": "絕對值是到原點的距離；設每段長為 1，用距離關係列式找原點。", "st": [["設定間距", "設 $\\overline{AB}=\\overline{BC}=\\overline{CD}=\\overline{DE}=1$。<br>因為 $|a|+|b|=|e|$，而 $E$ 在最右邊，原點應該在偏左的地方。先假設原點在 $\\overline{BC}$ 上，且原點到 $B$ 的距離為 $t$（$0\\le t\\le1$）。"], ["用距離列式", "- $|b|=t$<br>- $|a|=t+1$<br>- $|e|=3-t$（原點到 $E$ 隔著 3 段，扣掉 $t$）<br><br>$$(t+1)+t=3-t\\Rightarrow 3t=2\\Rightarrow t=\\frac{2}{3}$$<br><br>$t$ 在 0 與 1 之間，假設成立。"], ["判斷位置", "原點離 $B$ 是 $\\frac23$、離 $C$ 是 $\\frac13$，所以在 $\\overline{BC}$ 上且**較接近 $C$**。<br><br>（若原點在 $\\overline{CD}$ 上，$|a|+|b|$ 至少是 $2+1=3$，但 $|e|$ 最多是 2，不可能相等。）<br><br>答案是 (B)。"]], "tr": "把 $|a|$、$|b|$ 當成 $a$、$b$ 直接相加，忘了負數的絕對值要變正。"}, {"id": "114-16", "y": 114, "no": 16, "ch": "C13", "img": "img/hk/114_16.webp", "gimg": null, "a": 3, "rate": 0.5, "t": "平行線截比例線段", "c": "$\\overline{EF}\\parallel\\overline{BC}$ 得 $\\overline{AE}:\\overline{AB}=\\overline{AF}:\\overline{AC}$；判斷平行要看比例是否相等。", "st": [["用平行求出 E 的位置", "因為 $\\overline{EF}\\parallel\\overline{BC}$，<br>$$\\overline{AE}:\\overline{AB}=\\overline{AF}:\\overline{AC}=7:10$$<br>設 $\\overline{AB}=10$，則 $\\overline{AE}=7$、$\\overline{EB}=3$。$D$ 是中點，$\\overline{AD}=5$，所以 $\\overline{DE}=7-5=2$。<br>$$\\overline{DE}=2\\lt \\overline{EB}=3$$"], ["判斷 DF 與 EC 是否平行", "在 $\\triangle AEC$ 中，若 $\\overline{DF}\\parallel\\overline{EC}$，就必須<br>$$\\overline{AD}:\\overline{AE}=\\overline{AF}:\\overline{AC}$$<br>但 $\\overline{AD}:\\overline{AE}=5:7$，$\\overline{AF}:\\overline{AC}=7:10$，$\\frac57\\neq\\frac7{10}$，所以<b>不平行</b>。<br><br>答案是 (D)。"]], "tr": "把 $\\overline{AF}:\\overline{FC}=7:3$ 直接當成 $\\overline{AE}:\\overline{AB}$，比例的分母要用全長 $\\overline{AC}=10$。"}, {"id": "114-17", "y": 114, "no": 17, "ch": "C07", "img": "img/hk/114_17.webp", "gimg": null, "a": 3, "rate": 0.51, "t": "螺紋深度與正三角形高", "c": "兩側與鉛垂線夾 $30^\\circ$、頂角 $60^\\circ$，大三角形是正三角形，$H$ 是邊長的 $\\frac{\\sqrt3}{2}$ 倍。", "st": [["看出大三角形是正三角形", "頂角 $60^\\circ$，左右兩邊都和鉛垂線夾 $30^\\circ$，所以兩個底角都是 $90^\\circ-30^\\circ=60^\\circ$，三個角都是 $60^\\circ$，是<b>正三角形</b>，邊長就是螺紋間距，設為 $p$。"], ["求高 H", "正三角形的高是邊長的 $\\frac{\\sqrt3}{2}$ 倍（用畢氏定理：$\\sqrt{p^2-(\\frac p2)^2}=\\frac{\\sqrt3}{2}p$）：<br>$$H=\\frac{\\sqrt3}{2}p$$"], ["求螺紋深度", "螺紋深度 $=H-\\frac H8-\\frac H4=\\frac58H$，<br>$$\\frac58\\times\\frac{\\sqrt3}{2}p=\\frac{5\\sqrt3}{16}p$$<br><br>答案是 (D)。"]], "tr": "算出 $\\frac58H$ 就選 (A)，忘了題目問的是「間距」的幾倍，要把 $H$ 換成 $\\frac{\\sqrt3}{2}p$。"}, {"id": "114-18", "y": 114, "no": 18, "ch": "C02", "img": "img/hk/114_18.webp", "gimg": null, "a": 1, "rate": 0.44, "t": "三數的公因數與公倍數", "c": "三數的公因數一定也是其中兩數的公因數；三數的公倍數一定也是其中兩數的公倍數。", "st": [["判斷甲", "$a,b,c$ 的最大公因數能整除 $a$ 和 $b$，所以它是 $a,b$ 的公因數，一定是 $(a,b)=11$ 的因數，<b>不可能比 11 大</b>。甲錯誤。"], ["判斷乙", "$a,b,c$ 的最小公倍數是 $a$ 和 $b$ 的公倍數，所以一定是 $[a,b]=88$ 的倍數，<b>不可能比 88 小</b>。乙錯誤。<br><br>答案是 (B)。"]], "tr": "以為多一個數 $c$ 進來，公因數可能變大、公倍數可能變小；其實剛好相反，只會不變或往另一邊走。"}, {"id": "114-19", "y": 114, "no": 19, "ch": "C03", "img": "img/hk/114_19.webp", "gimg": null, "a": 2, "rate": 0.48, "t": "優惠方案買最多爆米花", "c": "爆米花用「優惠二」最划算，設 $x$ 張票用優惠二，列一元一次不等式。", "st": [["比較怎麼買最划算", "每人一定要一張票和一杯飲料。<br><br>- 用優惠一：飲料 35 元。<br>- 用優惠二：爆米花＋飲料 90 元，等於多付 $90-35=55$ 元就多一盒爆米花，比單買 80 元便宜。<br><br>所以爆米花都用優惠二來買。"], ["列不等式", "16 張票共 $16\\times320=5120$ 元。設 $x$ 張票用優惠二，其餘 $16-x$ 張用優惠一：<br>$$5120+90x+35(16-x)\\le6000$$<br>$$5680+55x\\le6000\\Rightarrow x\\le\\frac{320}{55}=5.8\\cdots$$<br>所以 $x$ 最大是 5。"], ["檢查剩下的錢", "$x=5$ 時花 $5680+275=5955$ 元，剩 45 元，不夠再單買一盒 80 元的爆米花。<br><br>最多 5 盒，答案是 (C)。"]], "tr": "忘了每人都要飲料，用剩下的 880 元直接除以 80 或 90；或沒檢查剩下的錢能不能再單買。"}, {"id": "114-20", "y": 114, "no": 20, "ch": "C11", "img": "img/hk/114_20.webp", "gimg": null, "a": 0, "rate": 0.35, "t": "摺紙角度與大邊對大角", "c": "摺疊前後角度不變；再用「三角形中大邊對大角」比較。", "st": [["摺疊後角度相等", "沿 $\\overline{BF}$ 摺，$C$ 落到 $P$，所以 $\\angle3=\\angle BFP$、$\\angle2=\\angle PBF$；<br>沿 $\\overline{FE}$ 摺，$D$ 落到 $P$，所以 $\\angle4=\\angle PFE$、$\\angle5=\\angle PEF$；<br>沿 $\\overline{BE}$ 摺，$A$ 落到 $P$，所以 $\\angle1=\\angle PBE$、$\\angle6=\\angle PEB$。"], ["求 ∠3+∠4", "$C、F、D$ 在一直線上，F 點的四個角合起來是平角：<br>$$\\angle3+\\angle BFP+\\angle PFE+\\angle4=180^\\circ\\Rightarrow2(\\angle3+\\angle4)=180^\\circ$$<br>所以 $\\angle3+\\angle4=90^\\circ$，同時 $\\angle BFE=90^\\circ$。"], ["比較 ∠1+∠2 與 ∠5+∠6", "$\\angle1+\\angle2=\\angle PBE+\\angle PBF=\\angle EBF$，<br>$\\angle5+\\angle6=\\angle PEF+\\angle PEB=\\angle BEF$。<br><br>在 $\\triangle BEF$ 中，$\\angle EBF$ 對邊是 $\\overline{FE}$，$\\angle BEF$ 對邊是 $\\overline{BF}$。因為 $\\overline{FE}\\gt \\overline{BF}$，大邊對大角：<br>$$\\angle EBF\\gt \\angle BEF\\Rightarrow\\angle1+\\angle2\\gt \\angle5+\\angle6$$<br><br>答案是 (A)。"]], "tr": "大邊對大角找錯對邊；或拿 $\\overline{BE}$ 最長來比較，其實要比的是 $\\overline{FE}$ 與 $\\overline{BF}$。"}, {"id": "114-21", "y": 114, "no": 21, "ch": "C10", "img": "img/hk/114_21.webp", "gimg": null, "a": 3, "rate": 0.44, "t": "拋物線平移與 y 截距", "c": "向右平移 $h$ 單位，圖形變成 $y=-(x+7-h)^2+12$；看 $x=0$ 時的 $y$ 值怎麼變。", "st": [["寫出平移後的函數", "向右平移 $h$ 單位（$0\\le h\\le10$），頂點從 $(-7,12)$ 移到 $(-7+h,12)$：<br>$$y=-(x+7-h)^2+12$$<br>與 $y$ 軸的交點 $P$ 的 $y$ 坐標是 $x=0$ 代入：<br>$$y_P=-(7-h)^2+12$$"], ["觀察變化", "- $h$ 從 0 增加到 7：$(7-h)^2$ 從 49 變小到 0，$y_P$ 從 $-37$ <b>上升</b>到 12。<br>- $h$ 從 7 增加到 10：$(7-h)^2$ 從 0 變大到 9，$y_P$ 從 12 <b>下降</b>到 3。<br><br>直觀想：開口向下的拋物線，頂點經過 $y$ 軸時 $P$ 在最高點，之前往上、之後往下。答案是 (D)。"]], "tr": "只比較起點和終點（$-37$ 變成 3），就以為持續向上；中間頂點會經過 $y$ 軸。"}, {"id": "114-22", "y": 114, "no": 22, "ch": "C15", "img": "img/hk/114_22.webp", "gimg": null, "a": 1, "rate": 0.33, "t": "重心與面積比", "c": "重心與兩頂點連成的三角形面積是全體的 $\\frac13$；同高三角形面積比等於底的比。", "st": [["先求 △ABG", "設 $\\triangle ABC$ 面積為 1。$G$ 是重心，重心和三個頂點把三角形分成三塊等面積，所以<br>$$\\triangle ABG=\\frac13$$"], ["求 △AEG", "$\\triangle AEG$ 和 $\\triangle ABG$ 同高（頂點都是 $G$），底 $\\overline{AE}:\\overline{AB}=3:7$：<br>$$\\triangle AEG=\\frac13\\times\\frac37=\\frac17$$"], ["求 △ADE 與 △ADG", "$\\triangle ADE$ 和 $\\triangle AEG$ 同高（頂點都是 $A$），底 $\\overline{DE}:\\overline{EG}=3:2$：<br>$$\\triangle ADE=\\frac17\\times\\frac32=\\frac{3}{14}$$<br>$$\\triangle ADG=\\frac{3}{14}+\\frac17=\\frac{5}{14}$$<br><br>答案是 (B)。"]], "tr": "把 $\\overline{AE}:\\overline{EB}=3:4$ 直接當成 $3:4$ 的面積比，忘了要用 $\\overline{AE}:\\overline{AB}=3:7$。"}, {"id": "114-23", "y": 114, "no": 23, "ch": "C14", "img": "img/hk/114_23.webp", "gimg": null, "a": 3, "rate": 0.3, "t": "旋轉三角形與圓周角", "c": "旋轉後 $\\overline{AB'}=\\overline{AB}$，等弦對等弧；再用圓周角等於所對弧的一半。", "st": [["算出 ∠BAC 和弧 AB", "$\\angle BAC$ 對弧 $\\overset{\\frown}{BC}=54^\\circ$，所以 $\\angle BAC=27^\\circ$。<br>經過 $C$ 的弧 $\\overset{\\frown}{AB}=54^\\circ+62^\\circ=116^\\circ$。"], ["利用等弦對等弧找 B'", "旋轉不改變長度，$\\overline{AB'}=\\overline{AB}$，等長的弦所對的弧也相等，所以另一側的 $\\overset{\\frown}{AB'}=116^\\circ$。<br>剩下不含 $A$ 的弧 $\\overset{\\frown}{BB'}=360^\\circ-116^\\circ-116^\\circ=128^\\circ$，<br>$$\\angle BAB'=\\frac{128^\\circ}{2}=64^\\circ$$"], ["求 x", "$\\angle C'AB'$ 就是旋轉後的 $\\angle CAB=27^\\circ$，<br>$$x=\\angle BAB'-\\angle C'AB'=64-27=37$$<br><br>答案是 (D)。"]], "tr": "把 $\\angle BAB'$ 當成旋轉角卻不知怎麼求；或忘了要扣掉 $\\angle C'AB'=27^\\circ$。"}, {"id": "114-24", "y": 114, "no": 24, "ch": "C05", "img": "img/hk/114_24.webp", "gimg": "img/hk/114_G24.webp", "a": 3, "rate": 0.72, "t": "齒輪比越大越費力", "c": "齒輪比＝前齒數÷後齒數，比較四個選項的齒輪比，最大的最費力。", "st": [["算出各選項的齒輪比", "- (A) $\\frac{33}{18}=\\frac{11}{6}\\approx1.83$<br>- (B) $\\frac{33}{24}=\\frac{11}{8}\\approx1.38$<br>- (C) $\\frac{22}{21}\\approx1.05$<br>- (D) $\\frac{44}{21}\\approx2.10$"], ["找最大的", "(D) 最大，最費力，答案是 (D)。<br><br><b>秒殺</b>：分子變大、分母變小都會讓分數變大。(A) 是把分母從 21 變成 18（變小 $\\frac{1}{7}$），(D) 是把分子從 33 變成 44（變大 $\\frac13$），(D) 變化幅度較大。"]], "tr": "以為後齒輪齒數越多越費力，選成 (B)；後齒數在分母，越多反而越省力。"}, {"id": "114-25", "y": 114, "no": 25, "ch": "C05", "img": "img/hk/114_25.webp", "gimg": "img/hk/114_G24.webp", "a": 1, "rate": 0.59, "t": "相同齒輪比的組合數", "c": "前齒數都是 11 的倍數（$11\\times2,3,4$），齒輪比 $\\frac{11}{k}$ 時後齒數必須是 $2k、3k、4k$。", "st": [["觀察前齒數", "前齒輪 $22=11\\times2$、$33=11\\times3$、$44=11\\times4$。<br>要讓（$11\\times m$）÷ 後齒數 $=\\frac{11}{k}$，後齒數必須是 $m\\times k$（$m=2,3,4$）。"], ["逐一檢查", "後齒輪有 14、16、18、21、24、28：<br><br>- $\\frac{11}{6}$：要 12、18、24 → 有 18、24，<b>2 種</b><br>- $\\frac{11}{7}$：要 14、21、28 → 三個都有，<b>3 種</b><br>- $\\frac{11}{8}$：要 16、24、32 → 有 16、24，<b>2 種</b><br>- $\\frac{11}{9}$：要 18、27、36 → 只有 18，<b>1 種</b><br><br>答案是 (B)。"]], "tr": "只約分前齒數不看後齒數，或漏掉 $\\frac{22}{14}$ 也等於 $\\frac{11}{7}$。"}, {"id": "115-1", "y": 115, "no": 1, "ch": "C04", "img": "img/hk/115_1.webp", "gimg": null, "a": 2, "rate": 0.83, "t": "加減消去求 x 值", "c": "兩式的 $y$ 係數剛好是 $+2y$ 與 $-2y$，相加就能把 $y$ 消掉。", "st": [["觀察係數，決定消去哪個未知數", "第一式有 $+2y$，第二式有 $-2y$，兩式<b>直接相加</b>，$y$ 就會抵消，只剩 $x$。"], ["兩式相加", "$$(x+2y)+(2x-2y)=5+1$$<br>$$3x=6 \\Rightarrow x=2$$"], ["代回檢查", "把 $x=2$ 代入第一式：$2+2y=5$，$y=\\frac{3}{2}$。<br>再代入第二式：$4-3=1$ 成立，所以 $x=2$，選 (C)。"]], "tr": "題目只問 $x$，別花時間算完 $y$ 卻把 $y$ 的值誤填成答案。"}, {"id": "115-2", "y": 115, "no": 2, "ch": "C16", "img": "img/hk/115_2.webp", "gimg": null, "a": 3, "rate": 0.82, "t": "直角柱的角度判斷", "c": "直角柱的底面是正三角形（每角 $60^\\circ$），側面都是長方形（每角 $90^\\circ$）。", "st": [["判斷 ∠ABC 在哪個面", "$A$、$B$、$C$ 三點都在上底面，而底面是正三角形，正三角形每個內角都是 $60^\\circ$，所以 $\\angle ABC=60^\\circ$。"], ["判斷 ∠BCF 在哪個面", "$B$、$C$、$F$ 在側面 $BCFE$ 上。直角柱的側稜垂直底面，所以每個側面都是<b>長方形</b>，長方形的角都是直角，$\\angle BCF=90^\\circ$。"], ["對照選項", "$\\angle ABC=60^\\circ$、$\\angle BCF=90^\\circ$，選 (D)。"]], "tr": "立體圖是斜著畫的，看起來不像直角就以為不是 $90^\\circ$；要用「直角柱側面是長方形」判斷，不能用眼睛量。"}, {"id": "115-3", "y": 115, "no": 3, "ch": "C07", "img": "img/hk/115_3.webp", "gimg": null, "a": 2, "rate": 0.77, "t": "化簡 √504 成最簡根式", "c": "把被開方數做質因數分解，找出最大的完全平方因數提到根號外。", "st": [["質因數分解 504", "$$504=2^3\\times 3^2\\times 7$$"], ["把成對的質因數提出來", "成對的有 $2^2$ 和 $3^2$，也就是完全平方數 $36$：<br>$$\\sqrt{504}=\\sqrt{36\\times 14}=6\\sqrt{14}$$<br>$14=2\\times7$ 已經沒有平方因數，所以這就是最簡根式。"], ["求 a+b", "$a=6$、$b=14$，$a+b=20$，選 (C)。"]], "tr": "只提出 $4$ 得到 $2\\sqrt{126}$ 就停下來（$126$ 還含 $9$），沒有化到最簡。"}, {"id": "115-4", "y": 115, "no": 4, "ch": "C16", "img": "img/hk/115_4.webp", "gimg": null, "a": 1, "rate": 0.81, "t": "兩袋抽球的點數和", "c": "兩袋各抽一球共 $3\\times3=9$ 種等可能結果，列表數出每種和出現幾次。", "st": [["列出所有結果", "甲袋 2、3、4，乙袋 3、4、5，各抽一球共 $3\\times 3=9$ 種，而且每種機會相等。用表格把和列出來：<br><br>- 甲抽 2：$2+3=5$、$2+4=6$、$2+5=7$<br>- 甲抽 3：$3+3=6$、$3+4=7$、$3+5=8$<br>- 甲抽 4：$4+3=7$、$4+4=8$、$4+5=9$"], ["數哪個和最多", "和為 7 出現 3 次，機率 $\\frac{3}{9}=\\frac{1}{3}$ 最大；6 和 8 各 2 次，5 和 9 各 1 次。所以選 (B)。"]], "tr": "以為和有 5~9 共 5 種、機率都是 $\\frac{1}{5}$；結果要用「9 種組合」來算，不是「5 種和」。"}, {"id": "115-5", "y": 115, "no": 5, "ch": "C01", "img": "img/hk/115_5.webp", "gimg": null, "a": 2, "rate": 0.76, "t": "提出公因數巧算", "c": "兩項都乘 $98.7$，用分配律提出來：$a\\times c-b\\times c=(a-b)\\times c$。", "st": [["找共同的乘數", "兩項都有 $\\times 98.7$，用分配律提出來，算式會變簡單：<br>$$2.45\\times98.7-(-0.55)\\times98.7=\\big(2.45-(-0.55)\\big)\\times 98.7$$"], ["先算括號", "減去負數等於加上正數：$2.45+0.55=3$。<br>$$3\\times 98.7=296.1$$"], ["判斷範圍", "$296.1$ 介於 $250$ 和 $300$ 之間，選 (C)。"]], "tr": "把「減去 $-0.55$」算成 $2.45-0.55=1.9$，得到 $187.53$ 誤選 (A)。"}, {"id": "115-6", "y": 115, "no": 6, "ch": "C16", "img": "img/hk/115_6.webp", "gimg": null, "a": 1, "rate": 0.77, "t": "雙向表挑出禮盒文旦", "c": "排除「良級」那一欄和「大果」那一列，剩下中間 4 格加起來。", "st": [["先想清楚要留下哪些", "「良級<b>或</b>大果」都不要，所以留下的必須「不是良級」而且「不是大果」，也就是：<br>小果、中果 × 優級、特級，共 4 格。"], ["把 4 格加起來", "$$180+270+100+80=630$$<br>共 630 公斤。"], ["另解：用總量扣掉", "總量 $800$，扣掉良級 $80$、扣掉大果 $100$，但「大果良級」$10$ 被扣了兩次，要加回一次：<br>$$800-80-100+10=630$$<br>選 (B)。"]], "tr": "直接用 $800-80-100=620$，忘了「大果且良級」的 10 公斤被重複扣掉，誤選 (A)。"}, {"id": "115-7", "y": 115, "no": 7, "ch": "C06", "img": "img/hk/115_7.webp", "gimg": null, "a": 0, "rate": 0.71, "t": "多項式長除法", "c": "用長除法求出商式與餘式，再相加。", "st": [["做長除法", "$4x^2\\div x=4x$，$4x(x+2)=4x^2+8x$，相減得 $-11x-5$。<br>$-11x\\div x=-11$，$-11(x+2)=-11x-22$，相減得 $17$。<br><br>所以商式 $4x-11$，餘式 $17$。"], ["驗算", "被除式 = 除式 × 商式 + 餘式：<br>$$(x+2)(4x-11)+17=4x^2-3x-22+17=4x^2-3x-5\\ \\checkmark$$"], ["相加", "$$(4x-11)+17=4x+6$$<br>選 (A)。"]], "tr": "相減時符號出錯：$-3x-8x=-11x$、$-5-(-22)=17$，常有人算成 $5x$ 或 $-27$。"}, {"id": "115-8", "y": 115, "no": 8, "ch": "C01", "img": "img/hk/115_8.webp", "gimg": null, "a": 2, "rate": 0.75, "t": "科學記號比大小", "c": "面積越大細菌越多，丁的大小介於乙和丙之間，數量也介於兩者之間。", "st": [["從圖比較區域大小", "圖中四個圓由小到大是：甲 &lt; 乙 &lt; 丁 &lt; 丙（丁比乙大，比丙小）。<br>因為細菌均勻分布、面積越大細菌越多，所以丁的數量要<b>介於乙和丙之間</b>。"], ["寫出範圍", "丁的細菌數介於 $7.3\times10^6$ 和 $5.4\times10^7$ 之間。"], ["比對選項", "- (A) $1.7\\times10^5$ 比乙小，不行。<br>- (B) $1.7\\times10^6$ 比 $7.3\\times10^6$ 小，不行。<br>- (C) $1.7\\times10^7=17000000$，介於 $7300000$ 和 $54000000$ 之間，可以。<br>- (D) $1.7\\times10^8$ 比丙還多，不行。<br><br>選 (C)。"]], "tr": "只看 $10$ 的次方、以為 $1.7\\times10^6$ 和 $7.3\\times10^6$ 差不多；同次方時還要比前面的數字。"}, {"id": "115-9", "y": 115, "no": 9, "ch": "C08", "img": "img/hk/115_9.webp", "gimg": null, "a": 1, "rate": 0.65, "t": "提公因式解二次方程", "c": "兩項都有 $(x+7)$，提出來後變成兩個一次式相乘等於 0。", "st": [["提出公因式", "兩項都有 $(x+7)$，不要展開，直接提出：<br>$$2x(x+7)-10(x+7)=(x+7)(2x-10)=0$$"], ["兩個數相乘等於 0，至少一個是 0", "$x+7=0$ 或 $2x-10=0$，得 $x=-7$ 或 $x=5$。"], ["依大小代入", "$a\\gt b$，所以 $a=5$、$b=-7$。<br>$$a+2b=5+2\\times(-7)=-9$$<br>選 (B)。"]], "tr": "把 $a$、$b$ 弄反（$a=-7,b=5$ 得 $3$），或兩邊同除 $(x+7)$ 而漏掉 $x=-7$ 這個根。"}, {"id": "115-10", "y": 115, "no": 10, "ch": "C05", "img": "img/hk/115_10.webp", "gimg": null, "a": 3, "rate": 0.64, "t": "依原價比分攤折扣", "c": "哥哥分攤的金額 = 折扣後總額 × 哥哥原價占總原價的比例。", "st": [["設未知數", "設妹妹的書原價 $x$ 元。兩人合買總原價 $720+x$ 元，滿 1100 折 200，實付 $720+x-200=520+x$ 元。"], ["依原價比分攤列式", "哥哥原價占總原價的 $\\frac{720}{720+x}$，所以<br>$$\\frac{720}{720+x}\\times(520+x)=600$$<br>$$720(520+x)=600(720+x)$$<br>$$374400+720x=432000+600x \\Rightarrow 120x=57600 \\Rightarrow x=480$$"], ["檢查條件", "總原價 $720+480=1200\\ge1100$，確實能折扣；妹妹 $480\\lt 1100$ 也符合「不到 1100」。選 (D)。<br><br><b>快解</b>：按比例分攤，表示每人都付原價的同一個比例。哥哥 $720$ 元付 $600$ 元，比例 $\\frac{600}{720}=\\frac{5}{6}$。所以總原價 $-200=\\frac{5}{6}\\times$ 總原價，總原價 $=1200$，妹妹 $=480$。"]], "tr": "把 200 元平分（各折 100）去算，或用「實付金額」而不是「原價」來算比例。"}, {"id": "115-11", "y": 115, "no": 11, "ch": "C01", "img": "img/hk/115_11.webp", "gimg": null, "a": 0, "rate": 0.69, "t": "由數線位置判斷正負", "c": "從 $P$ 在 $A$ 左邊推出 $b\\lt 0$，再由 $A$ 在 $B$ 左邊得 $a\\lt b\\lt 0$。", "st": [["從圖讀出大小關係", "數線上越左越小。<br>- $P$ 在 $A$ 左邊：$a+b\\lt a$，兩邊減 $a$ 得 $b\\lt 0$。<br>- $A$ 在 $B$ 左邊：$a\\lt b$。<br><br>所以 $a\\lt b\\lt 0$，$a$、$b$ 都是負數。"], ["判斷 b−a 的位置", "$b-a=b+(-a)$，因為 $a\\lt 0$，$-a$ 是正數，**$b$ 加上一個正數會變大**，所以 $b-a\\gt b$，$Q$ 在 $B$ 的右邊。<br><br>（也可以舉例：$a=-3$、$b=-1$，則 $a+b=-4$ 在最左邊符合圖；$b-a=2$，在 $B(-1)$ 右邊。）選 (A)。"]], "tr": "看到 $b-a$ 就以為比 $b$ 小；減去負數其實是加上正數，結果會往右移。"}, {"id": "115-12", "y": 115, "no": 12, "ch": "C11", "img": "img/hk/115_12.webp", "gimg": null, "a": 1, "rate": 0.64, "t": "SAS 全等求周長", "c": "$\\triangle BED\\cong\\triangle AFC$（SAS），把四邊形的邊換成已知長度。", "st": [["找出全等三角形", "題目給 $\\overline{BE}=\\overline{AF}$、$\\angle BED=\\angle AFC$、$\\overline{ED}=\\overline{FC}$，夾角兩邊都相等，所以<br>$$\\triangle BED\\cong\\triangle AFC$$<br>（SAS 全等）<br>對應頂點 $B\\leftrightarrow A$、$E\\leftrightarrow F$、$D\\leftrightarrow C$，因此 $\\overline{BD}=\\overline{AC}=9$。"], ["算出 AD", "$\\overline{AD}=\\overline{AB}-\\overline{BD}=15-9=6$。"], ["把周長換成已知邊", "$$\\overline{AD}+\\overline{DE}+\\overline{EF}+\\overline{FA}=6+\\overline{FC}+\\overline{EF}+\\overline{BE}$$<br>而 $\\overline{BE}+\\overline{EF}+\\overline{FC}=\\overline{BC}=16$，所以周長 $=6+16=22$，選 (B)。"]], "tr": "對應頂點找錯，以為 $\\overline{BD}=\\overline{AF}$；要依「相等的角的頂點 $E\\leftrightarrow F$」來對應。"}, {"id": "115-13", "y": 115, "no": 13, "ch": "C04", "img": "img/hk/115_13.webp", "gimg": null, "a": 3, "rate": 0.69, "t": "平行 x 軸的直線方程式", "c": "平行 $x$ 軸的水平線上，每一點的 $y$ 坐標都一樣，方程式寫成 $y=k$。", "st": [["想像水平線", "與 $x$ 軸平行的直線是<b>水平線</b>，線上的點左右移動時 $y$ 坐標不變。"], ["代入通過的點", "它通過 $(-3,-1)$，所以線上每一點的 $y$ 坐標都是 $-1$，方程式為 $y=-1$，選 (D)。"]], "tr": "把「平行 $x$ 軸」誤寫成 $x=-3$（那是鉛直線，平行 $y$ 軸）。"}, {"id": "115-14", "y": 115, "no": 14, "ch": "C10", "img": "img/hk/115_14.webp", "gimg": null, "a": 1, "rate": 0.62, "t": "二次函數的最大值", "c": "$-(x+5)^2\\le0$，所以 $y\\le-20$，圖形上所有點的 $y$ 坐標都不超過 $-20$。", "st": [["找出 y 的範圍", "任何數的平方都 $\\ge0$，所以 $(x+5)^2\\ge0$，$-(x+5)^2\\le0$，<br>$$y=-(x+5)^2-20\\le-20$$<br>圖形開口向下，頂點 $(-5,-20)$，最大值是 $-20$。"], ["逐一判斷", "- 【甲】$-15\\gt -20$，超過最大值，<b>錯誤</b>。<br>- 【乙】$25\\gt -20$，更不可能，<b>錯誤</b>。<br><br>兩人皆錯，選 (B)。"]], "tr": "誤以為 $-15$ 比 $-20$ 小而判斷甲正確；負數比大小時 $-15\\gt -20$。"}, {"id": "115-15", "y": 115, "no": 15, "ch": "C11", "img": "img/hk/115_15.webp", "gimg": null, "a": 2, "rate": 0.64, "t": "正六邊形旁的正 n 邊形", "c": "在 $\\triangle EDH$ 中用正六邊形的 $120^\\circ$ 與正 $n$ 邊形內角列方程式，求出內角再求 $n$。", "st": [["設正 n 邊形的內角", "設正 $n$ 邊形每個內角為 $\\theta$。因為 $G$、$F$、$E$ 共線，$\\angle FEH=\\angle GEH=\\theta$；又 $\\angle EHI=\\theta$，而 $D$、$H$、$I$ 共線，所以 $\\angle EHD=180^\\circ-\\theta$。"], ["找出三角形 EDH 的另外兩角", "正六邊形每個內角 $120^\\circ$。<br>- $C$、$D$、$H$ 共線：$\\angle EDH=180^\\circ-120^\\circ=60^\\circ$。<br>- 繞 $E$ 點一圈 $360^\\circ$：$\\angle FED+\\angle DEH+\\angle HEF=360^\\circ$，所以 $\\angle DEH=360^\\circ-120^\\circ-\\theta=240^\\circ-\\theta$。"], ["用三角形內角和", "$$60^\\circ+(240^\\circ-\\theta)+(180^\\circ-\\theta)=180^\\circ \\Rightarrow 2\\theta=300^\\circ \\Rightarrow \\theta=150^\\circ$$<br>每個外角 $180^\\circ-150^\\circ=30^\\circ$，外角和 $360^\\circ$，所以 $n=360\\div30=12$，選 (C)。"]], "tr": "把 $\\angle DEH$ 當成 $\\theta-120^\\circ$（以為 $\\overline{ED}$ 在內角裡面）；要看清楚 $\\overline{ED}$ 在正 $n$ 邊形的外面。"}, {"id": "115-16", "y": 115, "no": 16, "ch": "C15", "img": "img/hk/115_16.webp", "gimg": null, "a": 0, "rate": 0.5, "t": "斜邊中點與角平分線", "c": "直角三角形斜邊中點到三頂點等距（外心），所以 $\\overline{DA}=\\overline{DB}$，得等腰三角形。", "st": [["先算 ∠BAC 與 ∠BAE", "$\\angle BAC=180^\\circ-90^\\circ-40^\\circ=50^\\circ$。$\\overline{AE}$ 平分 $\\angle BAC$，所以 $\\angle BAE=25^\\circ$。"], ["用斜邊中點性質", "直角三角形的外心就在斜邊中點，所以 $D$ 到三頂點距離相等：$\\overline{DA}=\\overline{DB}$。<br>$\\triangle DAB$ 是等腰三角形，底角相等：$\\angle ABD=\\angle BAD=50^\\circ$。"], ["在三角形 ABE 中求角", "$E$ 在 $\\overline{BD}$ 上，所以 $\\angle ABE=50^\\circ$。<br>$$\\angle AEB=180^\\circ-25^\\circ-50^\\circ=105^\\circ$$<br>選 (A)。"]], "tr": "沒想到「斜邊中點到三頂點等距」，以為 $\\overline{BD}$ 是角平分線而得 $\\angle ABE=45^\\circ$，算出 $110^\\circ$。"}, {"id": "115-17", "y": 115, "no": 17, "ch": "C09", "img": "img/hk/115_17.webp", "gimg": null, "a": 0, "rate": 0.55, "t": "每年成長 2.5% 的用電量", "c": "每年都是前一年的 $1.025$ 倍，是等比數列；從 2023 到 2030 共乘 7 次。", "st": [["每年變成幾倍", "增加量是前一年的 $2.5\\%$，所以今年 = 前一年 $\\times(1+0.025)$ = 前一年 $\\times1.025$。"], ["數乘幾次", "- 2024 年：$2700\\times1.025$<br>- 2025 年：$2700\\times1.025^2$<br>- ……<br>- 2030 年：$2030-2023=7$，所以是 $2700\\times(1.025)^7$。<br><br>選 (A)。"]], "tr": "把 2024～2030 算成 8 年；或誤以為每年增加量固定是 $2700\\times0.025$（那是等差，選了 (C)）。"}, {"id": "115-18", "y": 115, "no": 18, "ch": "C14", "img": "img/hk/115_18.webp", "gimg": null, "a": 1, "rate": 0.48, "t": "菱形與圓的弦心距", "c": "$\\overline{BD}$ 是圓的弦，菱形對角線互相垂直平分，用畢氏定理求弦心距。", "st": [["用菱形性質找直角", "菱形對角線互相垂直平分。設 $\\overline{AC}$ 與 $\\overline{BD}$ 交於 $M$，則 $\\overline{BM}=12$，$\\overline{AC}\\perp\\overline{BD}$，而且 $\\overline{AM}=\\overline{MC}$。"], ["求 OM（弦心距）", "$O$ 在 $\\overline{AC}$ 上，$\\overline{OB}=13$ 是半徑。在直角 $\\triangle OMB$ 中：<br>$$\\overline{OM}=\\sqrt{13^2-12^2}=\\sqrt{25}=5$$"], ["求 CO", "$A$ 在圓上，$\\overline{OA}=13$，所以 $\\overline{AM}=13-5=8$，因此 $\\overline{MC}=8$。<br>$C$ 和 $O$ 在 $M$ 的同一側，$\\overline{CO}=\\overline{MC}-\\overline{MO}=8-5=3$，選 (B)。"]], "tr": "以為 $C$ 也在圓上，或把 $\\overline{AM}$ 當成 $13+5$；要從圖看出 $O$ 在 $M$ 和 $C$ 之間。"}, {"id": "115-19", "y": 115, "no": 19, "ch": "C14", "img": "img/hk/115_19.webp", "gimg": null, "a": 3, "rate": 0.45, "t": "圓內接長方形的位置", "c": "圓內接長方形的對角線都是直徑，所以 $E$ 在 $A$ 的正對面、$F$ 在 $B$ 的正對面（相隔 $180^\\circ$ 的弧）。", "st": [["為什麼對角線是直徑", "長方形 $ABEF$ 的 $\\angle ABE=90^\\circ$，是圓周角，所對的弧是 $180^\\circ$，所以 $\\overline{AE}$ 是直徑；同理 $\\overline{BF}$ 也是直徑。<br>因此從 $A$ 出發走 $180^\\circ$ 的弧到 $E$，從 $B$ 出發走 $180^\\circ$ 的弧到 $F$。"], ["找 E：從 A 經 B 走 180°", "$\\overset{\\frown}{AB}+\\overset{\\frown}{BC}=87^\\circ+91^\\circ=178^\\circ\\lt 180^\\circ$，再走 $2^\\circ$ 就到 $E$，而 $\\overset{\\frown}{CD}=88^\\circ$，所以 $E$ 在 $\\overset{\\frown}{CD}$ 上。"], ["找 F：從 B 經 C 走 180°", "$\\overset{\\frown}{BC}+\\overset{\\frown}{CD}=91^\\circ+88^\\circ=179^\\circ\\lt 180^\\circ$，再走 $1^\\circ$ 就到 $F$，所以 $F$ 在 $\\overset{\\frown}{AD}$ 上。<br><br>選 (D)。"]], "tr": "只憑圖的印象猜位置；四段弧都接近 $90^\\circ$，差 $1^\\circ$、$2^\\circ$ 就換一段弧，一定要累加計算。"}, {"id": "115-20", "y": 115, "no": 20, "ch": "C02", "img": "img/hk/115_20.webp", "gimg": null, "a": 2, "rate": 0.39, "t": "次大因數反推原數", "c": "除了自己以外最大的因數 = 原數 ÷ 它的最小質因數。", "st": [["關鍵觀念", "一個數 $M$ 除以越小的數，得到的因數越大。所以「除了 $M$ 之外最大的因數」$=M\\div p$，其中 $p$ 是 $M$ 的<b>最小質因數</b>。"], ["判斷甲：M 是多少", "$M=p\\times(2^2\\times11)$，$M$ 一定是 $2$ 的倍數，所以最小質因數 $p=2$，<br>$$M=2\\times44=88=2^3\\times11$$<br>$88\\div8=11$，**8 一定是 $M$ 的因數，甲正確**。"], ["判斷乙：N 可能是多少", "$N=q\\times(3\\times13)$，$N$ 是 $3$ 的倍數，所以最小質因數 $q$ 只能是 $2$ 或 $3$：<br>- $q=2$：$N=78$，最小質因數確實是 2，符合。<br>- $q=3$：$N=117=3^2\\times13$，最小質因數是 3，符合。<br><br>$N=78$ 時 $9$ 不是因數，所以「9 一定是 $N$ 的因數」<b>錯誤</b>。選 (C)。"]], "tr": "直接把 $N$ 當成 $3\\times39=117$，忘了 $q=2$ 時的 $78$ 也符合，誤判乙正確。"}, {"id": "115-21", "y": 115, "no": 21, "ch": "C13", "img": "img/hk/115_21.webp", "gimg": null, "a": 3, "rate": 0.37, "t": "平行線截比例線段", "c": "由內錯角相等得 $DE\\parallel AC$，再由等腰三角形求邊長，用平行線截比例線段求比。", "st": [["找平行與等腰", "- $\\angle DEA=\\angle EAC=65^\\circ$，是內錯角相等，所以直線 $DE\\parallel\\overline{AC}$。<br>- $\\triangle ABC$ 中 $\\angle BAC=\\angle C=65^\\circ$，所以 $\\overline{BC}=\\overline{BA}$。$\\overline{BC}=5+8=13$，故 $\\overline{AB}=13$。"], ["延長 DE 交 BC", "設直線 $DE$ 交 $\\overline{BC}$ 於 $G$。因 $\\overline{EG}\\parallel\\overline{AC}$，<br>$$\\frac{\\overline{BG}}{\\overline{BC}}=\\frac{\\overline{BE}}{\\overline{BA}}=\\frac{6}{13}\\Rightarrow\\overline{BG}=6$$<br>所以 $\\overline{GC}=7$；又 $\\overline{BF}=5\\lt 6$，$F$ 在 $B$、$G$ 之間，$\\overline{FG}=1$、$\\overline{FC}=8$。"], ["在 △FAC 中用平行線截比例", "$\\overline{PG}\\parallel\\overline{AC}$，所以<br>$$\\frac{\\overline{FP}}{\\overline{FA}}=\\frac{\\overline{FG}}{\\overline{FC}}=\\frac{1}{8}\\Rightarrow\\frac{\\overline{AP}}{\\overline{AF}}=\\frac{7}{8}$$<br>$\\overline{AP}:\\overline{AF}=7:8$，選 (D)。"]], "tr": "沒有發現 $DE\\parallel AC$，或沒看出 $\\triangle ABC$ 是等腰（$\\overline{AB}=13$），就找不到比例。"}, {"id": "115-22", "y": 115, "no": 22, "ch": "C12", "img": "img/hk/115_22.webp", "gimg": null, "a": 2, "rate": 0.27, "t": "平行四邊形內的等距點", "c": "平行四邊形對角線互相平分（甲對）；角平分線上的點到兩邊等距，但兩組對邊間的距離不同（乙錯）。", "st": [["判斷甲", "平行四邊形的對角線互相平分，$P$ 是 $\\overline{AC}$ 中點。過 $P$ 作垂直 $\\overline{AD}$、$\\overline{BC}$ 的線，交於 $M$、$N$，則 $\\triangle PAM\\cong\\triangle PCN$（AAS：$\\overline{PA}=\\overline{PC}$、對頂角、直角），所以 $\\overline{PM}=\\overline{PN}$。同理 $P$ 到 $\\overline{AB}$、$\\overline{CD}$ 也等距。<b>甲正確</b>。"], ["判斷乙：先看兩組對邊的距離", "設 $\\overline{AD}$ 與 $\\overline{BC}$ 的距離為 $h_1$，$\\overline{AB}$ 與 $\\overline{CD}$ 的距離為 $h_2$。用兩種方法算面積：<br>$$21h_1=20h_2\\Rightarrow h_2=\\frac{21}{20}h_1\\neq h_1$$"], ["乙的 P 點到各邊距離", "角平分線上的點到角的兩邊等距：$P$ 在 $\\angle C$ 平分線上，到 $\\overline{BC}$、$\\overline{CD}$ 等距；在 $\\angle D$ 平分線上，到 $\\overline{CD}$、$\\overline{DA}$ 等距。所以<br>$P$ 到 $\\overline{BC}$、$\\overline{CD}$、$\\overline{AD}$ 的距離都相等，而 $\\overline{AD}$、$\\overline{BC}$ 相距 $h_1$，所以這三個距離都是 $\\frac{h_1}{2}$。<br>但 $P$ 到 $\\overline{AB}$ $=h_2-\\frac{h_1}{2}=\\frac{11}{20}h_1\\neq\\frac{h_1}{2}$，所以 $P$ 到 $\\overline{AB}$、$\\overline{CD}$ 不等距，<b>乙錯誤</b>。選 (C)。"]], "tr": "以為乙的 $P$ 到四邊都等距；只有菱形（四邊等長、兩組高相等）才會成立，本題 $20\\neq21$。"}, {"id": "115-23", "y": 115, "no": 23, "ch": "C03", "img": "img/hk/115_23.webp", "gimg": "img/hk/115_G23.webp", "a": 1, "rate": 0.47, "t": "時速錶的合法範圍", "c": "設實際速率為 $v$，用「指示 $\\ge$ 實際」與「$120-v\\le\\frac{v}{10}+4$」兩個條件解出 $v$ 的範圍。", "st": [["最大值：指示不小於實際", "法規要求指示速率永不小於實際速率，指示是 $120$，所以實際速率 $\\le120$，最大值 $120$ 公里/小時。"], ["最小值：解一元一次不等式", "設實際速率為 $v$，代入法規關係式 $120-v\\le\\frac{v}{10}+4$，兩邊乘 10：<br>$$1200-10v\\le v+40\\Rightarrow1160\\le11v\\Rightarrow v\\ge105.45\\ldots$$"], ["依題目取概數", "最小值用無條件進入法取到個位：$106$。最大值 $120$。選 (B)。"]], "tr": "把 $105.45$ 四捨五入或捨去成 $105$ 誤選 (A)；$v$ 必須 $\\ge105.45$，$105$ 不合法，所以要進位。"}, {"id": "115-24", "y": 115, "no": 24, "ch": "C10", "img": "img/hk/115_24.webp", "gimg": "img/hk/115_G23.webp", "a": 1, "rate": 0.38, "t": "轉速與速率的單位換算", "c": "實際速率 = 輪胎轉速 × 輪胎周長，先把單位換成「圈/小時」和「公里」。", "st": [["換轉速單位", "1 小時 = 60 分鐘，$x$ 圈/分鐘 = $60x$ 圈/小時。"], ["換周長單位", "$200$ 公分 $=2$ 公尺 $=0.002$ 公里。"], ["代入關係式", "$$y=60x\\times0.002=0.12x$$<br>選 (B)。"]], "tr": "忘了把「每分鐘」換成「每小時」而選 (A)，或公分換公里時少一個 0。"}, {"id": "115-25", "y": 115, "no": 25, "ch": "C05", "img": "img/hk/115_25.webp", "gimg": "img/hk/115_G23.webp", "a": 3, "rate": 0.43, "t": "故障與換胎的速率比較", "c": "指示速率 = 測出轉速 × 設定周長，實際速率 = 實際轉速 × 實際周長，比較兩式哪個因數比較大。", "st": [["分析甲車", "甲的設定周長 = 實際周長，但測出轉速 <b>比實際高</b>。<br>指示 $60$ = (較高的轉速) × 周長；實際 $p$ = (較低的實際轉速) × 同樣的周長。周長一樣，轉速較低，所以 $p\\lt 60$。"], ["分析乙車", "乙的測出轉速 = 實際轉速，但設定的是原本周長，<b>實際輪胎周長比較小</b>。<br>指示 $60$ = 轉速 × (較大的原周長)；實際 $q$ = 同樣轉速 × (較小的新周長)，所以 $q\\lt 60$。"], ["結論", "$p\\lt 60$、$q\\lt 60$，選 (D)。"]], "tr": "把「指示」和「實際」搞反：以為儀器測得偏高，實際就比 60 快。其實是儀器「誇大」了，實際比較慢。"}];
